def _array_converter(self, func, sky, *args, ra_dec_order=False):
    """
    A helper function to support reading either a pair of arrays
    or a single Nx2 array.
    """

    def _return_list_of_arrays(axes, origin):
        try:
            axes = np.broadcast_arrays(*axes)
        except ValueError:
            raise ValueError(
                "Coordinate arrays are not broadcastable to each other")

        xy = np.hstack([x.reshape((x.size, 1)) for x in axes])

        if ra_dec_order and sky == 'input':
            xy = self._denormalize_sky(xy)
        output = func(xy, origin)
        if ra_dec_order and sky == 'output':
            output = self._normalize_sky(output)
            return (output[:, 0].reshape(axes[0].shape),
                    output[:, 1].reshape(axes[0].shape))
        return [output[:, i].reshape(axes[0].shape)
                for i in range(output.shape[1])]

    def _return_single_array(xy, origin):
        if xy.shape[-1] != self.naxis:
            raise ValueError(
                "When providing two arguments, the array must be "
                "of shape (N, {0})".format(self.naxis))
        if ra_dec_order and sky == 'input':
            xy = self._denormalize_sky(xy)
        result = func(xy, origin)
        if ra_dec_order and sky == 'output':
            result = self._normalize_sky(result)
        return result

    if len(args) == 2:
        try:
            xy, origin = args
            xy = np.asarray(xy)
            origin = int(origin)
        except Exception:
            raise TypeError(
                "When providing two arguments, they must be "
                "(coords[N][{0}], origin)".format(self.naxis))
        if self.naxis == 1 and len(xy.shape) == 1:
            return _return_list_of_arrays([xy], origin)
        return _return_single_array(xy, origin)

    elif len(args) == self.naxis + 1:
        axes = args[:-1]
        origin = args[-1]
        try:
            axes = [np.asarray(x) for x in axes]
            origin = int(origin)
        except Exception:
            raise TypeError(
                "When providing more than two arguments, they must be " +
                "a 1-D array for each axis, followed by an origin.")

        return _return_list_of_arrays(axes, origin)

    raise TypeError(
        "WCS projection has {0} dimensions, so expected 2 (an Nx{0} array "
        "and the origin argument) or {1} arguments (the position in each "
        "dimension, and the origin argument). Instead, {2} arguments were "
        "given.".format(
            self.naxis, self.naxis + 1, len(args)))

def delete(self):
    # sort instance collections
    for model, instances in self.data.items():
        self.data[model] = sorted(instances, key=attrgetter("pk"))

    # if possible, bring the models in an order suitable for databases that
    # don't support transactions or cannot defer constraint checks until the
    # end of a transaction.
    self.sort()
    # number of objects deleted for each model label
    deleted_counter = Counter()

    # Optimize for the case with a single obj and no dependencies
    if len(self.data) == 1 and len(instances) == 1:
        instance = list(instances)[0]
        if self.can_fast_delete(instance):
            with transaction.mark_for_rollback_on_error():
                count = sql.DeleteQuery(model).delete_batch([instance.pk], self.using)
            return count, {model._meta.label: count}

    with transaction.atomic(using=self.using, savepoint=False):
        # send pre_delete signals
        for model, obj in self.instances_with_model():
            if not model._meta.auto_created:
                signals.pre_delete.send(
                    sender=model, instance=obj, using=self.using
                )

        # fast deletes
        for qs in self.fast_deletes:
            count = qs._raw_delete(using=self.using)
            deleted_counter[qs.model._meta.label] += count

        # update fields
        for model, instances_for_fieldvalues in self.field_updates.items():
            for (field, value), instances in instances_for_fieldvalues.items():
                query = sql.UpdateQuery(model)
                query.update_batch([obj.pk for obj in instances],
                                   {field.name: value}, self.using)

        # reverse instance collections
        for instances in self.data.values():
            instances.reverse()

        # delete instances
        for model, instances in self.data.items():
            query = sql.DeleteQuery(model)
            pk_list = [obj.pk for obj in instances]
            count = query.delete_batch(pk_list, self.using)
            deleted_counter[model._meta.label] += count

            if not model._meta.auto_created:
                for obj in instances:
                    signals.post_delete.send(
                        sender=model, instance=obj, using=self.using
                    )

    # update collected instances
    for instances_for_fieldvalues in self.field_updates.values():
        for (field, value), instances in instances_for_fieldvalues.items():
            for obj in instances:
                setattr(obj, field.attname, value)
    for model, instances in self.data.items():
        for instance in instances:
            setattr(instance, model._meta.pk.attname, None)
    return sum(deleted_counter.values()), dict(deleted_counter)

def match(self, path):
    match = self.regex.search(path)
    if match:
        # RoutePattern doesn't allow non-named groups so args are ignored.
        kwargs = match.groupdict()
        for key, value in kwargs.items():
            converter = self.converters[key]
            try:
                kwargs[key] = converter.to_python(value)
            except ValueError:
                return None
        return path[match.end():], (), kwargs
    return None

def resolve(self, path):
    match = self.pattern.match(path)
    if match:
        new_path, args, kwargs = match
        # Pass any extra_kwargs as **kwargs.
        kwargs.update(self.default_args)
        return ResolverMatch(self.callback, args, kwargs, self.pattern.name, route=str(self.pattern))

def response_for_exception(request, exc):
    if isinstance(exc, Http404):
        if settings.DEBUG:
            response = debug.technical_404_response(request, exc)
        else:
            response = get_exception_response(request, get_resolver(get_urlconf()), 404, exc)

    elif isinstance(exc, PermissionDenied):
        response = get_exception_response(request, get_resolver(get_urlconf()), 403, exc)
        log_response(
            'Forbidden (Permission denied): %s', request.path,
            response=response,
            request=request,
            exc_info=sys.exc_info(),
        )

    elif isinstance(exc, MultiPartParserError):
        response = get_exception_response(request, get_resolver(get_urlconf()), 400, exc)
        log_response(
            'Bad request (Unable to parse request body): %s', request.path,
            response=response,
            request=request,
            exc_info=sys.exc_info(),
        )

    elif isinstance(exc, SuspiciousOperation):
        if isinstance(exc, (RequestDataTooBig, TooManyFieldsSent)):
            # POST data can't be accessed again, otherwise the original
            # exception would be raised.
            request._mark_post_parse_error()

        # The request logger receives events for any problematic request
        # The security logger receives events for all SuspiciousOperations
        security_logger = logging.getLogger('django.security.%s' % exc.__class__.__name__)
        security_logger.error(
            str(exc),
            extra={'status_code': 400, 'request': request},
        )
        if settings.DEBUG:
            response = debug.technical_500_response(request, *sys.exc_info(), status_code=400)
        else:
            response = get_exception_response(request, get_resolver(get_urlconf()), 400, exc)

    elif isinstance(exc, SystemExit):
        # Allow sys.exit() to actually exit. See tickets #1023 and #4701
        raise

    else:
        signals.got_request_exception.send(sender=None, request=request)
        response = handle_uncaught_exception(request, get_resolver(get_urlconf()), sys.exc_info())
        log_response(
            '%s: %s', response.reason_phrase, request.path,
            response=response,
            request=request,
            exc_info=sys.exc_info(),
        )

    # Force a TemplateResponse to be rendered.
    if not getattr(response, 'is_rendered', True) and callable(getattr(response, 'render', None)):
        response = response.render()

    return response

def resolve(self, path):
    path = str(path)  # path may be a reverse_lazy object
    tried = []
    match = self.pattern.match(path)
    if match:
        new_path, args, kwargs = match
        for pattern in self.url_patterns:
            try:
                sub_match = pattern.resolve(new_path)
            except Resolver404 as e:
                sub_tried = e.args[0].get('tried')
                if sub_tried is not None:
                    tried.extend([pattern] + t for t in sub_tried)
                else:
                    tried.append([pattern])
            else:
                if sub_match:
                    # Merge captured arguments in match with submatch
                    sub_match_dict = {**kwargs, **self.default_kwargs}
                    # Update the sub_match_dict with the kwargs from the sub_match.
                    sub_match_dict.update(sub_match.kwargs)
                    # If there are *any* named groups, ignore all non-named groups.
                    # Otherwise, pass all non-named arguments as positional arguments.
                    sub_match_args = sub_match.args
                    if not sub_match_dict:
                        sub_match_args = args + sub_match.args
                    current_route = '' if isinstance(pattern, URLPattern) else str(pattern.pattern)
                    return ResolverMatch(
                        sub_match.func,
                        sub_match_args,
                        sub_match_dict,
                        sub_match.url_name,
                        [self.app_name] + sub_match.app_names,
                        [self.namespace] + sub_match.namespaces,
                        self._join_route(current_route, sub_match.route),
                    )
                tried.append([pattern])
        raise Resolver404({'tried': tried, 'path': new_path})
    raise Resolver404({'path': path})

def technical_404_response(request, exception):
    """Create a technical 404 error response. `exception` is the Http404."""
    try:
        error_url = exception.args[0]['path']
    except (IndexError, TypeError, KeyError):
        error_url = request.path_info[1:]  # Trim leading slash

    try:
        tried = exception.args[0]['tried']
    except (IndexError, TypeError, KeyError):
        tried = []
    else:
        if (not tried or (                  # empty URLconf
            request.path == '/' and
            len(tried) == 1 and             # default URLconf
            len(tried[0]) == 1 and
            getattr(tried[0][0], 'app_name', '') == getattr(tried[0][0], 'namespace', '') == 'admin'
        )):
            return default_urlconf(request)

    urlconf = getattr(request, 'urlconf', settings.ROOT_URLCONF)
    if isinstance(urlconf, types.ModuleType):
        urlconf = urlconf.__name__

    caller = ''
    try:
        resolver_match = resolve(request.path)
    except Resolver404:
        pass
    else:
        obj = resolver_match.func

        if hasattr(obj, '__name__'):
            caller = obj.__name__
        elif hasattr(obj, '__class__') and hasattr(obj.__class__, '__name__'):
            caller = obj.__class__.__name__

        if hasattr(obj, '__module__'):
            module = obj.__module__
            caller = '%s.%s' % (module, caller)

    with Path(CURRENT_DIR, 'templates', 'technical_404.html').open(encoding='utf-8') as fh:
        t = DEBUG_ENGINE.from_string(fh.read())
    c = Context({
        'urlconf': urlconf,
        'root_urlconf': settings.ROOT_URLCONF,
        'request_path': error_url,
        'urlpatterns': tried,
        'reason': str(exception),
        'request': request,
        'settings': get_safe_settings(),
        'raising_view_name': caller,
    })
    return HttpResponseNotFound(t.render(c), content_type='text/html')

def match(self, path):
    match = self.regex.search(path)
    if match:
        # If there are any named groups, use those as kwargs, ignoring
        # non-named groups. Otherwise, pass all non-named arguments as
        # positional arguments.
        kwargs = {k: v for k, v in match.groupdict().items() if v is not None}
        args = () if kwargs else match.groups()
        return path[match.end():], args, kwargs
    return None

def display_for_field(value, field, empty_value_display):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    if getattr(field, 'flatchoices', None):
        return dict(field.flatchoices).get(value, empty_value_display)
    # BooleanField needs special-case null-handling, so it comes before the
    # general null test.
    elif isinstance(field, models.BooleanField):
        return _boolean_icon(value)
    elif value is None:
        return empty_value_display
    elif isinstance(field, models.DateTimeField):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(field, (models.DateField, models.TimeField)):
        return formats.localize(value)
    elif isinstance(field, models.DecimalField):
        return formats.number_format(value, field.decimal_places)
    elif isinstance(field, (models.IntegerField, models.FloatField)):
        return formats.number_format(value)
    elif isinstance(field, models.FileField) and value:
        return format_html('<a href="{}">{}</a>', value.url, value)
    else:
        return display_for_value(value, empty_value_display)

def display_for_value(value, empty_value_display, boolean=False):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    if boolean:
        return _boolean_icon(value)
    elif value is None:
        return empty_value_display
    elif isinstance(value, bool):
        return str(value)
    elif isinstance(value, datetime.datetime):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(value, (datetime.date, datetime.time)):
        return formats.localize(value)
    elif isinstance(value, (int, decimal.Decimal, float)):
        return formats.number_format(value)
    elif isinstance(value, (list, tuple)):
        return ', '.join(str(v) for v in value)
    else:
        return str(value)

def cleanse_setting(self, key, value):
    """
    Cleanse an individual setting key/value of sensitive content. If the
    value is a dictionary, recursively cleanse the keys in that dictionary.
    """
    try:
        if self.hidden_settings.search(key):
            cleansed = self.cleansed_substitute
        elif isinstance(value, dict):
            cleansed = {k: self.cleanse_setting(k, v) for k, v in value.items()}
        else:
            cleansed = value
    except TypeError:
        # If the key isn't regex-able, just return as-is.
        cleansed = value

    if callable(cleansed):
        cleansed = CallableSettingWrapper(cleansed)

    return cleansed

def get_combinator_sql(self, combinator, all):
    features = self.connection.features
    compilers = [
        query.get_compiler(self.using, self.connection)
        for query in self.query.combined_queries if not query.is_empty()
    ]
    if not features.supports_slicing_ordering_in_compound:
        for query, compiler in zip(self.query.combined_queries, compilers):
            if query.low_mark or query.high_mark:
                raise DatabaseError('LIMIT/OFFSET not allowed in subqueries of compound statements.')
            if compiler.get_order_by():
                raise DatabaseError('ORDER BY not allowed in subqueries of compound statements.')
    parts = ()
    for compiler in compilers:
        try:
            # If the columns list is limited, then all combined queries
            # must have the same columns list. Set the selects defined on
            # the query on all combined queries, if not already set.
            if not compiler.query.values_select and self.query.values_select:
                compiler.query = compiler.query.clone()
                compiler.query.set_values((
                    *self.query.extra_select,
                    *self.query.values_select,
                    *self.query.annotation_select,
                ))
            part_sql, part_args = compiler.as_sql()
            if compiler.query.combinator:
                # Wrap in a subquery if wrapping in parentheses isn't
                # supported.
                if not features.supports_parentheses_in_compound:
                    part_sql = 'SELECT * FROM ({})'.format(part_sql)
                # Add parentheses when combining with compound query if not
                # already added for all compound queries.
                elif not features.supports_slicing_ordering_in_compound:
                    part_sql = '({})'.format(part_sql)
            parts += ((part_sql, part_args),)
        except EmptyResultSet:
            # Omit the empty queryset with UNION and with DIFFERENCE if the
            # first queryset is nonempty.
            if combinator == 'union' or (combinator == 'difference' and parts):
                continue
            raise
    if not parts:
        raise EmptyResultSet
    combinator_sql = self.connection.ops.set_operators[combinator]
    if all and combinator == 'union':
        combinator_sql += ' ALL'
    braces = '({})' if features.supports_slicing_ordering_in_compound else '{}'
    sql_parts, args_parts = zip(*((braces.format(sql), args) for sql, args in parts))
    result = [' {} '.format(combinator_sql).join(sql_parts)]
    params = []
    for part in args_parts:
        params.extend(part)
    return result, params

def check_filterable(self, expression):
    """Raise an error if expression cannot be used in a WHERE clause."""
    if not getattr(expression, 'filterable', True):
        raise NotSupportedError(
            expression.__class__.__name__ + ' is disallowed in the filter '
            'clause.'
        )
    if hasattr(expression, 'get_source_expressions'):
        for expr in expression.get_source_expressions():
            self.check_filterable(expr)

def __lt__(self, other):
    # This is needed because bisect does not take a comparison function.
    if isinstance(other, Field):
        return self.creation_counter < other.creation_counter
    return NotImplemented

def handle(self, **options):
    # Execute the command and exit.
    if options['command']:
        exec(options['command'])
        return

    # Execute stdin if it has anything to read and exit.
    # Not supported on Windows due to select.select() limitations.
    if sys.platform != 'win32' and not sys.stdin.isatty() and select.select([sys.stdin], [], [], 0)[0]:
        exec(sys.stdin.read())
        return

    available_shells = [options['interface']] if options['interface'] else self.shells

    for shell in available_shells:
        try:
            return getattr(self, shell)(options)
        except ImportError:
            pass
    raise CommandError("Couldn't import {} interface.".format(shell))

def _get_default_pk_class(self):
    pk_class_path = getattr(
        self.app_config,
        'default_auto_field',
        settings.DEFAULT_AUTO_FIELD,
    )
    if self.app_config and self.app_config._is_default_auto_field_overridden:
        app_config_class = type(self.app_config)
        source = (
            f'{app_config_class.__module__}.'
            f'{app_config_class.__qualname__}.default_auto_field'
        )
    else:
        source = 'DEFAULT_AUTO_FIELD'
    if not pk_class_path:
        raise ImproperlyConfigured(f'{source} must not be empty.')
    try:
        pk_class = import_string(pk_class_path)
    except ImportError as e:
        msg = (
            f"{source} refers to the module '{pk_class_path}' that could "
            f"not be imported."
        )
        raise ImproperlyConfigured(msg) from e
    if not issubclass(pk_class, AutoField):
        raise ValueError(
            f"Primary key '{pk_class_path}' referred by {source} must "
            f"subclass AutoField."
        )
    return pk_class

def handle(self, app_or_project, name, target=None, **options):
    self.app_or_project = app_or_project
    self.a_or_an = 'an' if app_or_project == 'app' else 'a'
    self.paths_to_remove = []
    self.verbosity = options['verbosity']

    self.validate_name(name)

    # if some directory is given, make sure it's nicely expanded
    if target is None:
        top_dir = os.path.join(os.getcwd(), name)
        try:
            os.makedirs(top_dir)
        except FileExistsError:
            raise CommandError("'%s' already exists" % top_dir)
        except OSError as e:
            raise CommandError(e)
    else:
        if app_or_project == 'app':
            self.validate_name(os.path.basename(target), 'directory')
        top_dir = os.path.abspath(os.path.expanduser(target))
        if not os.path.exists(top_dir):
            raise CommandError("Destination directory '%s' does not "
                               "exist, please create it first." % top_dir)

    extensions = tuple(handle_extensions(options['extensions']))
    extra_files = []
    for file in options['files']:
        extra_files.extend(map(lambda x: x.strip(), file.split(',')))
    if self.verbosity >= 2:
        self.stdout.write(
            'Rendering %s template files with extensions: %s'
            % (app_or_project, ', '.join(extensions))
        )
        self.stdout.write(
            'Rendering %s template files with filenames: %s'
            % (app_or_project, ', '.join(extra_files))
        )
    base_name = '%s_name' % app_or_project
    base_subdir = '%s_template' % app_or_project
    base_directory = '%s_directory' % app_or_project
    camel_case_name = 'camel_case_%s_name' % app_or_project
    camel_case_value = ''.join(x for x in name.title() if x != '_')

    context = Context({
        **options,
        base_name: name,
        base_directory: top_dir,
        camel_case_name: camel_case_value,
        'docs_version': get_docs_version(),
        'django_version': django.__version__,
    }, autoescape=False)

    # Setup a stub settings environment for template rendering
    if not settings.configured:
        settings.configure()
        django.setup()

    template_dir = self.handle_template(options['template'],
                                        base_subdir)
    prefix_length = len(template_dir) + 1

    for root, dirs, files in os.walk(template_dir):

        path_rest = root[prefix_length:]
        relative_dir = path_rest.replace(base_name, name)
        if relative_dir:
            target_dir = os.path.join(top_dir, relative_dir)
            os.makedirs(target_dir, exist_ok=True)

        for dirname in dirs[:]:
            if dirname.startswith('.') or dirname == '__pycache__':
                dirs.remove(dirname)

        for filename in files:
            if filename.endswith(('.pyo', '.pyc', '.py.class')):
                # Ignore some files as they cause various breakages.
                continue
            old_path = os.path.join(root, filename)
            new_path = os.path.join(
                top_dir, relative_dir, filename.replace(base_name, name)
            )
            for old_suffix, new_suffix in self.rewrite_template_suffixes:
                if new_path.endswith(old_suffix):
                    new_path = new_path[:-len(old_suffix)] + new_suffix
                    break  # Only rewrite once

            if os.path.exists(new_path):
                raise CommandError(
                    "%s already exists. Overlaying %s %s into an existing "
                    "directory won't replace conflicting files." % (
                        new_path, self.a_or_an, app_or_project,
                    )
                )

            # Only render the Python files, as we don't want to
            # accidentally render Django templates files
            if new_path.endswith(extensions) or filename in extra_files:
                with open(old_path, encoding='utf-8') as template_file:
                    content = template_file.read()
                template = Engine().from_string(content)
                content = template.render(context)
                with open(new_path, 'w', encoding='utf-8') as new_file:
                    new_file.write(content)
            else:
                shutil.copyfile(old_path, new_path)

            if self.verbosity >= 2:
                self.stdout.write('Creating %s' % new_path)
            try:
                shutil.copymode(old_path, new_path)
                self.make_writeable(new_path)
            except OSError:
                self.stderr.write(
                    "Notice: Couldn't set permission bits on %s. You're "
                    "probably using an uncommon filesystem setup. No "
                    "problem." % new_path, self.style.NOTICE)

    if self.paths_to_remove:
        if self.verbosity >= 2:
            self.stdout.write('Cleaning up temporary files.')
        for path_to_remove in self.paths_to_remove:
            if os.path.isfile(path_to_remove):
                os.remove(path_to_remove)
            else:
                shutil.rmtree(path_to_remove)

class ReadOnlyPasswordHashWidget(forms.Widget):
    template_name = 'auth/widgets/read_only_password_hash.html'
    read_only = True

    def get_context(self, name, value, attrs):
        context = super().get_context(name, value, attrs)
        summary = []
        if not value or value.startswith(UNUSABLE_PASSWORD_PREFIX):
            summary.append({'label': gettext("No password set.")})
        else:
            try:
                hasher = identify_hasher(value)
            except ValueError:
                summary.append({'label': gettext("Invalid password format or unknown hashing algorithm.")})
            else:
                for key, value_ in hasher.safe_summary(value).items():
                    summary.append({'label': gettext(key), 'value': value_})
        context['summary'] = summary
        return context

def label_tag(self, contents=None, attrs=None, label_suffix=None):
    """
    Wrap the given contents in a <label>, if the field has an ID attribute.
    contents should be mark_safe'd to avoid HTML escaping. If contents
    aren't given, use the field's HTML-escaped label.

    If attrs are given, use them as HTML attributes on the <label> tag.

    label_suffix overrides the form's label_suffix.
    """
    contents = contents or self.label
    if label_suffix is None:
        label_suffix = (self.field.label_suffix if self.field.label_suffix is not None
                        else self.form.label_suffix)
    # Only add the suffix if the label does not end in punctuation.
    # Translators: If found as last label character, these punctuation
    # characters will prevent the default label_suffix to be appended to the label
    if label_suffix and contents and contents[-1] not in _(':?.!'):
        contents = format_html('{}{}', contents, label_suffix)
    widget = self.field.widget
    id_ = widget.attrs.get('id') or self.auto_id
    if id_:
        id_for_label = widget.id_for_label(id_)
        if id_for_label:
            attrs = {**(attrs or {}), 'for': id_for_label}
        if self.field.required and hasattr(self.form, 'required_css_class'):
            attrs = attrs or {}
            if 'class' in attrs:
                attrs['class'] += ' ' + self.form.required_css_class
            else:
                attrs['class'] = self.form.required_css_class
        attrs = flatatt(attrs) if attrs else ''
        contents = format_html('<label{}>{}</label>', attrs, contents)
    else:
        contents = conditional_escape(contents)
    return mark_safe(contents)

def default(self, obj):
    if isinstance(obj, Message):
        # Using 0/1 here instead of False/True to produce more compact json
        is_safedata = 1 if isinstance(obj.message, SafeData) else 0
        message = [self.message_key, is_safedata, obj.level, obj.message]
        if obj.extra_tags:
            message.append(obj.extra_tags)
        return message
    return super().default(obj)

def decode(self, s, **kwargs):
    decoded = super().decode(s, **kwargs)
    return self.process_messages(decoded)

def process_messages(self, obj):
    if isinstance(obj, list) and obj:
        if obj[0] == MessageEncoder.message_key:
            if obj[1]:
                obj[3] = mark_safe(obj[3])
            return Message(*obj[2:])
        return [self.process_messages(item) for item in obj]
    if isinstance(obj, dict):
        return {key: self.process_messages(value)
                for key, value in obj.items()}
    return obj

class DatabaseClient(BaseDatabaseClient):
    executable_name = "psql"

    @classmethod
    def settings_to_cmd_args_env(cls, settings_dict, parameters):
        args = [cls.executable_name]
        options = settings_dict.get("OPTIONS", {})

        host = settings_dict.get("HOST")
        port = settings_dict.get("PORT")
        dbname = settings_dict.get("NAME")
        user = settings_dict.get("USER")
        passwd = settings_dict.get("PASSWORD")
        passfile = options.get("passfile")
        service = options.get("service")
        sslmode = options.get("sslmode")
        sslrootcert = options.get("sslrootcert")
        sslcert = options.get("sslcert")
        sslkey = options.get("sslkey")

        if not dbname and not service:
            # Connect to the default 'postgres' db.
            dbname = "postgres"
        if user:
            args += ["-U", user]
        if host:
            args += ["-h", host]
        if port:
            args += ["-p", str(port)]
        if dbname:
            args += [dbname]
        args.extend(parameters)

        env = {}
        if passwd:
            env["PGPASSWORD"] = str(passwd)
        if service:
            env["PGSERVICE"] = str(service)
        if sslmode:
            env["PGSSLMODE"] = str(sslmode)
        if sslrootcert:
            env["PGSSLROOTCERT"] = str(sslrootcert)
        if sslcert:
            env["PGSSLCERT"] = str(sslcert)
        if sslkey:
            env["PGSSLKEY"] = str(sslkey)
        if passfile:
            env["PGPASSFILE"] = str(passfile)
        return args, (env or None)

    def runshell(self, parameters):
        sigint_handler = signal.getsignal(signal.SIGINT)
        try:
            # Allow SIGINT to pass to psql to abort queries.
            signal.signal(signal.SIGINT, signal.SIG_IGN)
            super().runshell(parameters)
        finally:
            # Restore the original SIGINT handler.
            signal.signal(signal.SIGINT, sigint_handler)

class BaseDatabaseClient:
    """Encapsulate backend-specific methods for opening a client shell."""

    # This should be a string representing the name of the executable
    # (e.g., "psql"). Subclasses must override this.
    executable_name = None

    def __init__(self, connection):
        # connection is an instance of BaseDatabaseWrapper.
        self.connection = connection

    @classmethod
    def settings_to_cmd_args_env(cls, settings_dict, parameters):
        raise NotImplementedError(
            "subclasses of BaseDatabaseClient must provide a "
            "settings_to_cmd_args_env() method or override a runshell()."
        )

    def runshell(self, parameters):
        args, env = self.settings_to_cmd_args_env(
            self.connection.settings_dict, parameters
        )
        env = {**os.environ, **env} if env else None
        subprocess.run(args, env=env, check=True)

class Command(BaseCommand):
    help = (
        "Runs the command-line client for specified database, or the "
        "default database if none is provided."
    )

    requires_system_checks = []

    def add_arguments(self, parser):
        parser.add_argument(
            "--database",
            default=DEFAULT_DB_ALIAS,
            help=(
                "Nominates a database onto which to open a shell. Defaults to the "
                '"default" database.'
            ),
        )
        parameters = parser.add_argument_group("parameters", prefix_chars="--")
        parameters.add_argument("parameters", nargs="*")

    def handle(self, **options):
        connection = connections[options["database"]]
        try:
            connection.client.runshell(options["parameters"])
        except FileNotFoundError:
            # Note that we're assuming the FileNotFoundError relates to the
            # command missing. It could be raised for some other reason, in
            # which case this error message would be inaccurate. Still, this
            # message catches the common case.
            raise CommandError(
                "You appear not to have the %r program installed or on your path."
                % connection.client.executable_name
            )
        except subprocess.CalledProcessError as e:
            raise CommandError(
                '"%s" returned non-zero exit status %s.'
                % (
                    " ".join(e.cmd),
                    e.returncode,
                ),
                returncode=e.returncode,
            )

def display_for_field(value, field, empty_value_display):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    if getattr(field, "flatchoices", None):
        try:
            return dict(field.flatchoices).get(value, empty_value_display)
        except TypeError:
            # Allow list-like choices.
            flatchoices = make_hashable(field.flatchoices)
            value = make_hashable(value)
            return dict(flatchoices).get(value, empty_value_display)

    # BooleanField needs special-case null-handling, so it comes before the
    # general null test.
    elif isinstance(field, models.BooleanField):
        return _boolean_icon(value)
    elif value is None:
        return empty_value_display
    elif isinstance(field, models.DateTimeField):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(field, (models.DateField, models.TimeField)):
        return formats.localize(value)
    elif isinstance(field, models.DecimalField):
        return formats.number_format(value, field.decimal_places)
    elif isinstance(field, (models.IntegerField, models.FloatField)):
        return formats.number_format(value)
    elif isinstance(field, models.FileField) and value:
        return format_html('<a href="{}">{}</a>', value.url, value)
    elif isinstance(field, models.JSONField) and value:
        try:
            return json.dumps(value, ensure_ascii=False, cls=field.encoder)
        except TypeError:
            return display_for_value(value, empty_value_display)
    else:
        return display_for_value(value, empty_value_display)

def _get_only_select_mask(self, opts, mask, select_mask=None):
    if select_mask is None:
        select_mask = {}
    select_mask[opts.pk] = {}
    # Only include fields mentioned in the mask.
    for field_name, field_mask in mask.items():
        field = opts.get_field(field_name)
        field_select_mask = select_mask.setdefault(field, {})
        if field_mask:
            if not field.is_relation:
                raise FieldError(next(iter(field_mask)))
            related_model = field.remote_field.model._meta.concrete_model
            self._get_only_select_mask(
                related_model._meta, field_mask, field_select_mask
            )
    return select_mask

def get_select_mask(self):
    """
    Convert the self.deferred_loading data structure to an alternate data
    structure, describing the field that *will* be loaded. This is used to
    compute the columns to select from the database and also by the
    QuerySet class to work out which fields are being initialized on each
    model. Models that have all their fields included aren't mentioned in
    the result, only those that have field restrictions in place.
    """
    field_names, defer = self.deferred_loading
    if not field_names:
        return {}
    mask = {}
    for field_name in field_names:
        part_mask = mask
        for part in field_name.split(LOOKUP_SEP):
            part_mask = part_mask.setdefault(part, {})
    opts = self.get_meta()
    if defer:
        return self._get_defer_select_mask(opts, mask)
    return self._get_only_select_mask(opts, mask)

def inverse(self, value):
    if not self.scaled():
        raise ValueError("Not invertible until both vmin and vmax are set")
    (vmin,), _ = self.process_value(self.vmin)
    (vmax,), _ = self.process_value(self.vmax)

    if np.iterable(value):
        val = np.ma.asarray(value)
        return vmin + val * (vmax - vmin)
    else:
        return vmin + value * (vmax - vmin)

    def draw_text(self, gc, x, y, s, prop, angle, ismath=False, mtext=None):
        # docstring inherited

        if self._is_transparent(gc.get_rgb()):
            return  # Special handling for fully transparent.

        if ismath == 'TeX':
            return self.draw_tex(gc, x, y, s, prop, angle)

        if ismath:
            return self.draw_mathtext(gc, x, y, s, prop, angle)

        if mpl.rcParams['ps.useafm']:
            font = self._get_font_afm(prop)
            scale = 0.001 * prop.get_size_in_points()
            stream = []
            thisx = 0
            last_name = None  # kerns returns 0 for None.
            xs_names = []
            for c in s:
                name = uni2type1.get(ord(c), f"uni{ord(c):04X}")
                try:
                    width = font.get_width_from_char_name(name)
                except KeyError:
                    name = 'question'
                    width = font.get_width_char('?')
                kern = font.get_kern_dist_from_name(last_name, name)
                last_name = name
                thisx += kern * scale
                xs_names.append((thisx, name))
                thisx += width * scale
            ps_name = (font.postscript_name
                       .encode("ascii", "replace").decode("ascii"))
            stream.append((ps_name, xs_names))

        else:
            font = self._get_font_ttf(prop)
            self._character_tracker.track(font, s)
            stream = []
            prev_font = curr_stream = None
            for item in _text_helpers.layout(s, font):
                ps_name = (item.ft_object.postscript_name
                           .encode("ascii", "replace").decode("ascii"))
                if item.ft_object is not prev_font:
                    if curr_stream:
                        stream.append(curr_stream)
                    prev_font = item.ft_object
                    curr_stream = [ps_name, []]
                curr_stream[1].append(
                    (item.x, item.ft_object.get_glyph_name(item.glyph_idx))
                )
            # append the last entry
            stream.append(curr_stream)

        self.set_color(*gc.get_rgb())

        for ps_name, xs_names in stream:
            self.set_font(ps_name, prop.get_size_in_points(), False)
            thetext = "\n".join(f"{x:g} 0 m /{name:s} glyphshow"
                                for x, name in xs_names)
            self._pswriter.write(f"""\
gsave
{self._get_clip_cmd(gc)}
{x:g} {y:g} translate
{angle:g} rotate
{thetext}
grestore
""")

class AxisDict(dict):
    def __init__(self, axes):
        self.axes = axes
        super().__init__()

    def __getitem__(self, k):
        if isinstance(k, tuple):
            r = SimpleChainedObjects(
                # super() within a list comprehension needs explicit args.
                [super(Axes.AxisDict, self).__getitem__(k1) for k1 in k])
            return r
        elif isinstance(k, slice):
            if k.start is None and k.stop is None and k.step is None:
                return SimpleChainedObjects(list(self.values()))
            else:
                raise ValueError("Unsupported slice")
        else:
            return dict.__getitem__(self, k)

    def __call__(self, *v, **kwargs):
        return maxes.Axes.axis(self.axes, *v, **kwargs)

def register(self, app: "Flask", options: dict) -> None:
    """Called by :meth:`Flask.register_blueprint` to register all
    views and callbacks registered on the blueprint with the
    application. Creates a :class:`.BlueprintSetupState` and calls
    each :meth:`record` callbackwith it.

    :param app: The application this blueprint is being registered
        with.
    :param options: Keyword arguments forwarded from
        :meth:`~Flask.register_blueprint`.
    :param first_registration: Whether this is the first time this
        blueprint has been registered on the application.
    """
    first_registration = False

    if self.name in app.blueprints:
        assert app.blueprints[self.name] is self, (
            "A name collision occurred between blueprints"
            f" {self!r} and {app.blueprints[self.name]!r}."
            f" Both share the same name {self.name!r}."
            f" Blueprints that are created on the fly need unique"
            f" names."
        )
    else:
        app.blueprints[self.name] = self
        first_registration = True

    self._got_registered_once = True
    state = self.make_setup_state(app, options, first_registration)

    if self.has_static_folder:
        state.add_url_rule(
            f"{self.static_url_path}/<path:filename>",
            view_func=self.send_static_file,
            endpoint="static",
        )

    # Merge blueprint data into parent.
    if first_registration:

        def extend(bp_dict, parent_dict):
            for key, values in bp_dict.items():
                key = self.name if key is None else f"{self.name}.{key}"

                parent_dict[key].extend(values)

        for key, value in self.error_handler_spec.items():
            key = self.name if key is None else f"{self.name}.{key}"
            value = defaultdict(
                dict,
                {
                    code: {
                        exc_class: func for exc_class, func in code_values.items()
                    }
                    for code, code_values in value.items()
                },
            )
            app.error_handler_spec[key] = value

        for endpoint, func in self.view_functions.items():
            app.view_functions[endpoint] = func

        extend(self.before_request_funcs, app.before_request_funcs)
        extend(self.after_request_funcs, app.after_request_funcs)
        extend(
            self.teardown_request_funcs,
            app.teardown_request_funcs,
        )
        extend(self.url_default_functions, app.url_default_functions)
        extend(self.url_value_preprocessors, app.url_value_preprocessors)
        extend(self.template_context_processors, app.template_context_processors)

    for deferred in self.deferred_functions:
        deferred(state)

    cli_resolved_group = options.get("cli_group", self.cli_group)

    if self.cli.commands:
        if cli_resolved_group is None:
            app.cli.commands.update(self.cli.commands)
        elif cli_resolved_group is _sentinel:
            self.cli.name = self.name
            app.cli.add_command(self.cli)
        else:
            self.cli.name = cli_resolved_group
            app.cli.add_command(self.cli)

    for blueprint, bp_options in self._blueprints:
        url_prefix = options.get("url_prefix", "")
        if "url_prefix" in bp_options:
            url_prefix = (
                url_prefix.rstrip("/") + "/" + bp_options["url_prefix"].lstrip("/")
            )

        bp_options["url_prefix"] = url_prefix
        bp_options["name_prefix"] = options.get("name_prefix", "") + self.name + "."
        blueprint.register(app, bp_options)

def iter_content(self, chunk_size=1, decode_unicode=False):
    """Iterates over the response data.  When stream=True is set on the
    request, this avoids reading the content at once into memory for
    large responses.  The chunk size is the number of bytes it should
    read into memory.  This is not necessarily the length of each item
    returned as decoding can take place.

    If decode_unicode is True, content will be decoded using the best
    available encoding based on the response.
    """

    def generate():
        # Special case for urllib3.
        if hasattr(self.raw, 'stream'):
            try:
                for chunk in self.raw.stream(chunk_size, decode_content=True):
                    yield chunk
            except ProtocolError as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
            except ReadTimeoutError as e:
                raise ConnectionError(e)
        else:
            # Standard file-like object.
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk

        self._content_consumed = True

    if self._content_consumed and isinstance(self._content, bool):
        raise StreamConsumedError()
    # simulate reading small chunks of the content
    reused_chunks = iter_slices(self._content, chunk_size)

    stream_chunks = generate()

    chunks = reused_chunks if self._content_consumed else stream_chunks

    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)

    return chunks

def content(self):
    """Content of the response, in bytes."""

    if self._content is False:
        # Read the contents.
        try:
            if self._content_consumed:
                raise RuntimeError(
                    'The content for this response was already consumed')

            if self.status_code == 0:
                self._content = None
            else:
                self._content = bytes().join(self.iter_content(CONTENT_CHUNK_SIZE)) or bytes()

        except AttributeError:
            self._content = None

    self._content_consumed = True
    # don't need to release the connection; that's been handled by urllib3
    # since we exhausted the data.
    return self._content

def __repr__(self):
    return "{}, grouped over {!r} \n{!r} groups with labels {}.".format(
        self.__class__.__name__,
        self._unique_coord.name,
        self._unique_coord.size,
        ", ".join(format_array_flat(self._unique_coord, 30).split()),
    )

def run(self, mod: ast.Module) -> None:
    """Find all assert statements in *mod* and rewrite them."""
    if not mod.body:
        # Nothing to do.
        return

    # We'll insert some special imports at the top of the module, but after any
    # docstrings and __future__ imports, so first figure out where that is.
    doc = getattr(mod, "docstring", None)
    expect_docstring = doc is None
    if doc is not None and self.is_rewrite_disabled(doc):
        return
    pos = 0
    item = None
    for item in mod.body:
        if (
            expect_docstring
            and isinstance(item, ast.Expr)
            and isinstance(item.value, ast.Constant)
        ):
            doc = item.value.value
            if self.is_rewrite_disabled(doc):
                return
            expect_docstring = False
        elif (
            isinstance(item, ast.ImportFrom)
            and item.level == 0
            and item.module == "__future__"
        ):
            pass
        else:
            break
        pos += 1
    # Special case: for a decorated function, set the lineno to that of the
    # first decorator, not the `def`. Issue #4984.
    if isinstance(item, ast.FunctionDef) and item.decorator_list:
        lineno = item.decorator_list[0].lineno
    else:
        lineno = item.lineno
    # Now actually insert the special imports.
    if sys.version_info >= (3, 10):
        aliases = [
            ast.alias("builtins", "@py_builtins", lineno=lineno, col_offset=0),
            ast.alias(
                "_pytest.assertion.rewrite",
                "@pytest_ar",
                lineno=lineno,
                col_offset=0,
            ),
        ]
    else:
        aliases = [
            ast.alias("builtins", "@py_builtins"),
            ast.alias("_pytest.assertion.rewrite", "@pytest_ar"),
        ]
    imports = [
        ast.Import([alias], lineno=lineno, col_offset=0) for alias in aliases
    ]
    mod.body[pos:pos] = imports

    # Collect asserts.
    nodes: List[ast.AST] = [mod]
    while nodes:
        node = nodes.pop()
        for name, field in ast.iter_fields(node):
            if isinstance(field, list):
                new: List[ast.AST] = []
                for i, child in enumerate(field):
                    if isinstance(child, ast.Assert):
                        # Transform assert.
                        new.extend(self.visit(child))
                    else:
                        new.append(child)
                        if isinstance(child, ast.AST):
                            nodes.append(child)
                setattr(node, name, new)
            elif (
                isinstance(field, ast.AST)
                # Don't recurse into expressions as they can't contain
                # asserts.
                and not isinstance(field, ast.expr)
            ):
                nodes.append(field)

def _diff_text(left, right, verbose=0):
    """Return the explanation for the diff between text or bytes.

    Unless --verbose is used this will skip leading and trailing
    characters which are identical to keep the diff minimal.

    If the input are bytes they will be safely converted to text.
    """
    from difflib import ndiff

    explanation = []

    def escape_for_readable_diff(binary_text):
        """
        Ensures that the internal string is always valid unicode, converting any bytes safely to valid unicode.
        This is done using repr() which then needs post-processing to fix the encompassing quotes and un-escape
        newlines and carriage returns (#429).
        """
        r = str(repr(binary_text)[1:-1])
        r = r.replace(r"\n", "\n")
        r = r.replace(r"\r", "\r")
        return r

    if isinstance(left, bytes):
        left = escape_for_readable_diff(left)
    if isinstance(right, bytes):
        right = escape_for_readable_diff(right)
    if verbose < 1:
        i = 0  # just in case left or right has zero length
        for i in range(min(len(left), len(right))):
            if left[i] != right[i]:
                break
        if i > 42:
            i -= 10  # Provide some context
            explanation = [
                "Skipping %s identical leading characters in diff, use -v to show" % i
            ]
            left = left[i:]
            right = right[i:]
        if len(left) == len(right):
            for i in range(len(left)):
                if left[-i] != right[-i]:
                    break
            if i > 42:
                i -= 10  # Provide some context
                explanation += [
                    "Skipping {} identical trailing "
                    "characters in diff, use -v to show".format(i)
                ]
                left = left[:-i]
                right = right[:-i]
    keepends = True
    if left.isspace() or right.isspace():
        left = repr(str(left))
        right = repr(str(right))
        explanation += ["Strings contain only whitespace, escaping them using repr()"]
    explanation += [
        line.strip("\n")
        for line in ndiff(left.splitlines(keepends), right.splitlines(keepends))
    ]
    return explanation

def _compare_eq_sequence(left, right, verbose=0):
    explanation = []
    len_left = len(left)
    len_right = len(right)
    for i in range(min(len_left, len_right)):
        if left[i] != right[i]:
            explanation += [
                "At index {} diff: {!r} != {!r}".format(i, left[i], right[i])
            ]
            break
    len_diff = len_left - len_right

    if len_diff:
        if len_diff > 0:
            dir_with_more = "Left"
            extra = saferepr(left[len_right])
        else:
            len_diff = 0 - len_diff
            dir_with_more = "Right"
            extra = saferepr(right[len_left])

        if len_diff == 1:
            explanation += [
                "{} contains one more item: {}".format(dir_with_more, extra)
            ]
        else:
            explanation += [
                "%s contains %d more items, first extra item: %s"
                % (dir_with_more, len_diff, extra)
            ]
    return explanation

def assertrepr_compare(config, op, left, right):
    """Return specialised explanations for some operators/operands"""
    width = 80 - 15 - len(op) - 2  # 15 chars indentation, 1 space around op
    left_repr = saferepr(left, maxsize=int(width // 2))
    right_repr = saferepr(right, maxsize=width - len(left_repr))

    summary = "{} {} {}".format(left_repr, op, right_repr)

    verbose = config.getoption("verbose")
    explanation = None
    try:
        if op == "==":
            if istext(left) and istext(right):
                explanation = _diff_text(left, right, verbose)
            else:
                if issequence(left) and issequence(right):
                    explanation = _compare_eq_sequence(left, right, verbose)
                elif isset(left) and isset(right):
                    explanation = _compare_eq_set(left, right, verbose)
                elif isdict(left) and isdict(right):
                    explanation = _compare_eq_dict(left, right, verbose)
                elif type(left) == type(right) and (isdatacls(left) or isattrs(left)):
                    type_fn = (isdatacls, isattrs)
                    explanation = _compare_eq_cls(left, right, verbose, type_fn)
                elif verbose > 0:
                    explanation = _compare_eq_verbose(left, right)
                if isiterable(left) and isiterable(right):
                    expl = _compare_eq_iterable(left, right, verbose)
                    if explanation is not None:
                        explanation.extend(expl)
                    else:
                        explanation = expl
        elif op == "not in":
            if istext(left) and istext(right):
                explanation = _notin_text(left, right, verbose)
    except outcomes.Exit:
        raise
    except Exception:
        explanation = [
            "(pytest_assertion plugin: representation of details failed.  "
            "Probably an object has a faulty __repr__.)",
            str(_pytest._code.ExceptionInfo.from_current()),
        ]

    if not explanation:
        return None

    return [summary] + explanation

def _add_prefix_for_feature_names_out(self, transformer_with_feature_names_out):
    """Add prefix for feature names out that includes the transformer names.

    Parameters
    ----------
    transformer_with_feature_names_out : list of tuples of (str, array-like of str)
        The tuple consistent of the transformer's name and its feature names out.

    Returns
    -------
    feature_names_out : ndarray of shape (n_features,), dtype=str
        Transformed feature names.
    """
    if self.verbose_feature_names_out:
        # Prefix the feature names out with the transformers name
        names = list(
            chain.from_iterable(
                (f"{name}__{i}" for i in feature_names_out)
                for name, feature_names_out in transformer_with_feature_names_out
            )
        )
        return np.asarray(names, dtype=object)

    # verbose_feature_names_out is False
    # Check that names are all unique without a prefix
    feature_names_count = Counter(
        chain.from_iterable(s for _, s in transformer_with_feature_names_out)
    )
    top_6_overlap = [
        name for name, count in feature_names_count.most_common(6) if count > 1
    ]
    top_6_overlap.sort()
    if top_6_overlap:
        if len(top_6_overlap) == 6:
            # There are more than 5 overlapping names, we only show the 5
            # of the feature names
            names_repr = str(top_6_overlap[:5])[:-1] + ", ...]"
        else:
            names_repr = str(top_6_overlap)
        raise ValueError(
            f"Output feature names: {names_repr} are not unique. Please set "
            "verbose_feature_names_out=True to add prefixes to feature names"
        )

    return np.concatenate(
        [name for _, name in transformer_with_feature_names_out],
    )

def _iter(self, fitted=False, replace_strings=False, column_as_strings=False):
    """
    Generate (name, trans, column, weight) tuples.

    If fitted=True, use the fitted transformers, else use the
    user specified transformers updated with converted column names
    and potentially appended with transformer for remainder.

    """
    if fitted:
        if replace_strings:
            # Replace "passthrough" with the fitted version in
            # _name_to_fitted_passthrough
            def replace_passthrough(name, trans, columns):
                if name not in self._name_to_fitted_passthrough:
                    return name, trans, columns
                return name, self._name_to_fitted_passthrough[name], columns

            transformers = [
                replace_passthrough(*trans) for trans in self.transformers_
            ]
        else:
            transformers = self.transformers_
    else:
        # interleave the validated column specifiers
        transformers = [
            (name, trans, column)
            for (name, trans, _), column in zip(self.transformers, self._columns)
        ]
        # add transformer tuple for remainder
        if self._remainder[2]:
            transformers = chain(transformers, [self._remainder])
    get_weight = (self.transformer_weights or {}).get

    output_config = _get_output_config("transform", self)
    for name, trans, columns in transformers:
        if replace_strings:
            # replace 'passthrough' with identity transformer and
            # skip in case of 'drop'
            if trans == "passthrough":
                trans = FunctionTransformer(
                    accept_sparse=True,
                    check_inverse=False,
                    feature_names_out="one-to-one",
                ).set_output(transform=output_config["dense"])
            elif trans == "drop":
                continue
            elif _is_empty_column_selection(columns):
                continue

        if column_as_strings:
            # Convert all columns to using their string labels
            columns_is_scalar = np.isscalar(columns)

            indices = self._transformer_to_input_indices[name]
            columns = self.feature_names_in_[indices]

            if columns_is_scalar:
                # selection is done with one dimension
                columns = columns[0]

        yield (name, trans, columns, get_weight(name))

def _hstack(self, Xs):
    """Stacks Xs horizontally.

    This allows subclasses to control the stacking behavior, while reusing
    everything else from ColumnTransformer.

    Parameters
    ----------
    Xs : list of {array-like, sparse matrix, dataframe}
    """
    if self.sparse_output_:
        try:
            # since all columns should be numeric before stacking them
            # in a sparse matrix, `check_array` is used for the
            # dtype conversion if necessary.
            converted_Xs = [
                check_array(X, accept_sparse=True, force_all_finite=False)
                for X in Xs
            ]
        except ValueError as e:
            raise ValueError(
                "For a sparse output, all columns should "
                "be a numeric or convertible to a numeric."
            ) from e

        return sparse.hstack(converted_Xs).tocsr()
    else:
        Xs = [f.toarray() if sparse.issparse(f) else f for f in Xs]
        config = _get_output_config("transform", self)
        if config["dense"] == "pandas" and all(hasattr(X, "iloc") for X in Xs):
            pd = check_pandas_support("transform")
            output = pd.concat(Xs, axis=1)

            # If all transformers define `get_feature_names_out`, then transform
            # will adjust the column names to be consistent with
            # verbose_feature_names_out. Here we prefix the feature names if
            # verbose_feature_names_out=True.

            if not self.verbose_feature_names_out:
                return output

            transformer_names = [
                t[0] for t in self._iter(fitted=True, replace_strings=True)
            ]
            feature_names_outs = [X.columns for X in Xs]
            names_out = self._add_prefix_for_feature_names_out(
                list(zip(transformer_names, feature_names_outs))
            )
            output.columns = names_out
            return output

        return np.hstack(Xs)

def _fit_transform(self, X, y, func, fitted=False, column_as_strings=False):
    """
    Private function to fit and/or transform on demand.

    Return value (transformers and/or transformed X data) depends
    on the passed function.
    ``fitted=True`` ensures the fitted transformers are used.
    """
    transformers = list(
        self._iter(
            fitted=fitted, replace_strings=True, column_as_strings=column_as_strings
        )
    )
    try:
        return Parallel(n_jobs=self.n_jobs)(
            delayed(func)(
                transformer=clone(trans) if not fitted else trans,
                X=_safe_indexing(X, column, axis=1),
                y=y,
                weight=weight,
                message_clsname="ColumnTransformer",
                message=self._log_message(name, idx, len(transformers)),
            )
            for idx, (name, trans, column, weight) in enumerate(transformers, 1)
        )
    except ValueError as e:
        if "Expected 2D array, got 1D array instead" in str(e):
            raise ValueError(_ERR_MSG_1DCOLUMN) from e
        else:
            raise

def add_directive_header(self, sig: str) -> None:
    super().add_directive_header(sig)
    sourcename = self.get_sourcename()
    if not self.options.annotation:
        # obtain annotation for this data
        try:
            annotations = get_type_hints(self.parent)
        except NameError:
            # Failed to evaluate ForwardRef (maybe TYPE_CHECKING)
            annotations = safe_getattr(self.parent, '__annotations__', {})
        except TypeError:
            annotations = {}
        except KeyError:
            # a broken class found (refs: https://github.com/sphinx-doc/sphinx/issues/8084)
            annotations = {}
        except AttributeError:
            # AttributeError is raised on 3.5.2 (fixed by 3.5.3)
            annotations = {}

        if self.objpath[-1] in annotations:
            objrepr = stringify_typehint(annotations.get(self.objpath[-1]))
            self.add_line('   :type: ' + objrepr, sourcename)
        else:
            key = ('.'.join(self.objpath[:-1]), self.objpath[-1])
            if self.analyzer and key in self.analyzer.annotations:
                self.add_line('   :type: ' + self.analyzer.annotations[key],
                              sourcename)

        try:
            if self.object is UNINITIALIZED_ATTR:
                pass
            else:
                objrepr = object_description(self.object)
                self.add_line('   :value: ' + objrepr, sourcename)
        except ValueError:
            pass
    elif self.options.annotation is SUPPRESS:
        pass
    else:
        self.add_line('   :annotation: %s' % self.options.annotation,
                      sourcename)

