def should_generate_module_page(app: Sphinx, modname: str) -> bool:
    """Check generation of module page is needed."""
    module_filename = get_module_filename(app, modname)
    if module_filename is None:
        # Always (re-)generate module page when module filename is not found.
        return True

    builder = cast(StandaloneHTMLBuilder, app.builder)
    basename = modname.replace('.', '/') + builder.out_suffix
    page_filename = path.join(app.outdir, '_modules/', basename)

    try:
        if path.getmtime(module_filename) <= path.getmtime(page_filename):
            # generation is not needed if the HTML page is newer than module file.
            return False
    except IOError:
        pass

    return True

def gen_pages_from_extensions(self) -> None:
    # pages from extensions
    for pagelist in self.events.emit('html-collect-pages'):
        for pagename, context, template in pagelist:
            self.handle_page(pagename, context, template)

def __new__(cls, num, dps=None, prec=None, precision=None):
    if prec is not None:
        SymPyDeprecationWarning(
                        feature="Using 'prec=XX' to denote decimal precision",
                        useinstead="'dps=XX' for decimal precision and 'precision=XX' "\
                                          "for binary precision",
                        issue=12820,
                        deprecated_since_version="1.1").warn()
        dps = prec
    del prec  # avoid using this deprecated kwarg

    if dps is not None and precision is not None:
        raise ValueError('Both decimal and binary precision supplied. '
                         'Supply only one. ')

    if isinstance(num, string_types):
        num = num.replace(' ', '')
        if num.startswith('.') and len(num) > 1:
            num = '0' + num
        elif num.startswith('-.') and len(num) > 2:
            num = '-0.' + num[2:]
    elif isinstance(num, float) and num == 0:
        num = '0'
    elif isinstance(num, (SYMPY_INTS, Integer)):
        num = str(num)  # faster than mlib.from_int
    elif num is S.Infinity:
        num = '+inf'
    elif num is S.NegativeInfinity:
        num = '-inf'
    elif type(num).__module__ == 'numpy': # support for numpy datatypes
        num = _convert_numpy_types(num)
    elif isinstance(num, mpmath.mpf):
        if precision is None:
            if dps is None:
                precision = num.context.prec
        num = num._mpf_

    if dps is None and precision is None:
        dps = 15
        if isinstance(num, Float):
            return num
        if isinstance(num, string_types) and _literal_float(num):
            try:
                Num = decimal.Decimal(num)
            except decimal.InvalidOperation:
                pass
            else:
                isint = '.' not in num
                num, dps = _decimal_to_Rational_prec(Num)
                if num.is_Integer and isint:
                    dps = max(dps, len(str(num).lstrip('-')))
                dps = max(15, dps)
                precision = mlib.libmpf.dps_to_prec(dps)
    elif precision == '' and dps is None or precision is None and dps == '':
        if not isinstance(num, string_types):
            raise ValueError('The null string can only be used when '
            'the number to Float is passed as a string or an integer.')
        ok = None
        if _literal_float(num):
            try:
                Num = decimal.Decimal(num)
            except decimal.InvalidOperation:
                pass
            else:
                isint = '.' not in num
                num, dps = _decimal_to_Rational_prec(Num)
                if num.is_Integer and isint:
                    dps = max(dps, len(str(num).lstrip('-')))
                    precision = mlib.libmpf.dps_to_prec(dps)
                ok = True
        if ok is None:
            raise ValueError('string-float not recognized: %s' % num)

    # decimal precision(dps) is set and maybe binary precision(precision)
    # as well.From here on binary precision is used to compute the Float.
    # Hence, if supplied use binary precision else translate from decimal
    # precision.

    if precision is None or precision == '':
        precision = mlib.libmpf.dps_to_prec(dps)

    precision = int(precision)

    if isinstance(num, float):
        _mpf_ = mlib.from_float(num, precision, rnd)
    elif isinstance(num, string_types):
        _mpf_ = mlib.from_str(num, precision, rnd)
    elif isinstance(num, decimal.Decimal):
        if num.is_finite():
            _mpf_ = mlib.from_str(str(num), precision, rnd)
        elif num.is_nan():
            _mpf_ = _mpf_nan
        elif num.is_infinite():
            if num > 0:
                _mpf_ = _mpf_inf
            else:
                _mpf_ = _mpf_ninf
        else:
            raise ValueError("unexpected decimal value %s" % str(num))
    elif isinstance(num, tuple) and len(num) in (3, 4):
        if type(num[1]) is str:
            # it's a hexadecimal (coming from a pickled object)
            # assume that it is in standard form
            num = list(num)
            num[1] = long(num[1], 16)
            _mpf_ = tuple(num)
        else:
            if len(num) == 4:
                # handle normalization hack
                return Float._new(num, precision)
            else:
                return (S.NegativeOne**num[0]*num[1]*S(2)**num[2]).evalf(precision)
    else:
        try:
            _mpf_ = num._as_mpf_val(precision)
        except (NotImplementedError, AttributeError):
            _mpf_ = mpmath.mpf(num, prec=precision)._mpf_

    # special cases
    if _mpf_ == _mpf_zero:
        pass  # we want a Float
    elif _mpf_ == _mpf_nan:
        return S.NaN

    obj = Expr.__new__(cls)
    obj._mpf_ = _mpf_
    obj._prec = precision
    return obj

def _print_Poly(self, expr):
    ATOM_PREC = PRECEDENCE["Atom"] - 1
    terms, gens = [], [ self.parenthesize(s, ATOM_PREC) for s in expr.gens ]

    for monom, coeff in expr.terms():
        s_monom = []

        for i, exp in enumerate(monom):
            if exp > 0:
                if exp == 1:
                    s_monom.append(gens[i])
                else:
                    s_monom.append(gens[i] + "**%d" % exp)

        s_monom = "*".join(s_monom)

        if coeff.is_Add:
            if s_monom:
                s_coeff = "(" + self._print(coeff) + ")"
            else:
                s_coeff = self._print(coeff)
        else:
            if s_monom:
                if coeff is S.One:
                    terms.extend(['+', s_monom])
                    continue

                if coeff is S.NegativeOne:
                    terms.extend(['-', s_monom])
                    continue

            s_coeff = self._print(coeff)

        if not s_monom:
            s_term = s_coeff
        else:
            s_term = s_coeff + "*" + s_monom

        if s_term.startswith('-'):
            terms.extend(['-', s_term[1:]])
        else:
            terms.extend(['+', s_term])

    if terms[0] in ['-', '+']:
        modifier = terms.pop(0)

        if modifier == '-':
            terms[0] = '-' + terms[0]

    format = expr.__class__.__name__ + "(%s, %s"

    from sympy.polys.polyerrors import PolynomialError

    try:
        format += ", modulus=%s" % expr.get_modulus()
    except PolynomialError:
        format += ", domain='%s'" % expr.get_domain()

    format += ")"

    for index, item in enumerate(gens):
        if len(item) > 2 and (item[:1] == "(" and item[len(item) - 1:] == ")"):
            gens[index] = item[1:len(item) - 1]

    return format % (' '.join(terms), ', '.join(gens))

def _print_MatMul(self, expr):
    from sympy import Add, MatAdd, HadamardProduct, MatMul, Mul

    parens = lambda x: self.parenthesize(x, precedence_traditional(expr), False)

    args = expr.args
    if isinstance(args[0], Mul):
        args = args[0].as_ordered_factors() + list(args[1:])
    else:
        args = list(args)

    if isinstance(expr, MatMul) and _coeff_isneg(expr):
        if args[0] == -1:
            args = args[1:]
        else:
            args[0] = -args[0]
        return '- ' + ' '.join(map(parens, args))
    else:
        return ' '.join(map(parens, args))

def from_index_summation(expr, first_index=None, last_index=None, dimensions=None):
    r"""
    Parse expression of matrices with explicitly summed indices into a
    matrix expression without indices, if possible.

    This transformation expressed in mathematical notation:

    `\sum_{j=0}^{N-1} A_{i,j} B_{j,k} \Longrightarrow \mathbf{A}\cdot \mathbf{B}`

    Optional parameter ``first_index``: specify which free index to use as
    the index starting the expression.

    Examples
    ========

    >>> from sympy import MatrixSymbol, MatrixExpr, Sum, Symbol
    >>> from sympy.abc import i, j, k, l, N
    >>> A = MatrixSymbol("A", N, N)
    >>> B = MatrixSymbol("B", N, N)
    >>> expr = Sum(A[i, j]*B[j, k], (j, 0, N-1))
    >>> MatrixExpr.from_index_summation(expr)
    A*B

    Transposition is detected:

    >>> expr = Sum(A[j, i]*B[j, k], (j, 0, N-1))
    >>> MatrixExpr.from_index_summation(expr)
    A.T*B

    Detect the trace:

    >>> expr = Sum(A[i, i], (i, 0, N-1))
    >>> MatrixExpr.from_index_summation(expr)
    Trace(A)

    More complicated expressions:

    >>> expr = Sum(A[i, j]*B[k, j]*A[l, k], (j, 0, N-1), (k, 0, N-1))
    >>> MatrixExpr.from_index_summation(expr)
    A*B.T*A.T
    """
    from sympy import Sum, Mul, Add, MatMul, transpose, trace
    from sympy.strategies.traverse import bottom_up

    def remove_matelement(expr, i1, i2):

        def repl_match(pos):
            def func(x):
                if not isinstance(x, MatrixElement):
                    return False
                if x.args[pos] != i1:
                    return False
                if x.args[3-pos] == 0:
                    if x.args[0].shape[2-pos] == 1:
                        return True
                    else:
                        return False
                return True
            return func

        expr = expr.replace(repl_match(1),
            lambda x: x.args[0])
        expr = expr.replace(repl_match(2),
            lambda x: transpose(x.args[0]))

        # Make sure that all Mul are transformed to MatMul and that they
        # are flattened:
        rule = bottom_up(lambda x: reduce(lambda a, b: a*b, x.args) if isinstance(x, (Mul, MatMul)) else x)
        return rule(expr)

    def recurse_expr(expr, index_ranges={}):
        if expr.is_Mul:
            nonmatargs = []
            pos_arg = []
            pos_ind = []
            dlinks = {}
            link_ind = []
            counter = 0
            args_ind = []
            for arg in expr.args:
                retvals = recurse_expr(arg, index_ranges)
                assert isinstance(retvals, list)
                if isinstance(retvals, list):
                    for i in retvals:
                        args_ind.append(i)
                else:
                    args_ind.append(retvals)
            for arg_symbol, arg_indices in args_ind:
                if arg_indices is None:
                    nonmatargs.append(arg_symbol)
                    continue
                if isinstance(arg_symbol, MatrixElement):
                    arg_symbol = arg_symbol.args[0]
                pos_arg.append(arg_symbol)
                pos_ind.append(arg_indices)
                link_ind.append([None]*len(arg_indices))
                for i, ind in enumerate(arg_indices):
                    if ind in dlinks:
                        other_i = dlinks[ind]
                        link_ind[counter][i] = other_i
                        link_ind[other_i[0]][other_i[1]] = (counter, i)
                    dlinks[ind] = (counter, i)
                counter += 1
            counter2 = 0
            lines = {}
            while counter2 < len(link_ind):
                for i, e in enumerate(link_ind):
                    if None in e:
                        line_start_index = (i, e.index(None))
                        break
                cur_ind_pos = line_start_index
                cur_line = []
                index1 = pos_ind[cur_ind_pos[0]][cur_ind_pos[1]]
                while True:
                    d, r = cur_ind_pos
                    if pos_arg[d] != 1:
                        if r % 2 == 1:
                            cur_line.append(transpose(pos_arg[d]))
                        else:
                            cur_line.append(pos_arg[d])
                    next_ind_pos = link_ind[d][1-r]
                    counter2 += 1
                    # Mark as visited, there will be no `None` anymore:
                    link_ind[d] = (-1, -1)
                    if next_ind_pos is None:
                        index2 = pos_ind[d][1-r]
                        lines[(index1, index2)] = cur_line
                        break
                    cur_ind_pos = next_ind_pos
            ret_indices = list(j for i in lines for j in i)
            lines = {k: MatMul.fromiter(v) if len(v) != 1 else v[0] for k, v in lines.items()}
            return [(Mul.fromiter(nonmatargs), None)] + [
                (MatrixElement(a, i, j), (i, j)) for (i, j), a in lines.items()
            ]
        elif expr.is_Add:
            res = [recurse_expr(i) for i in expr.args]
            d = collections.defaultdict(list)
            for res_addend in res:
                scalar = 1
                for elem, indices in res_addend:
                    if indices is None:
                        scalar = elem
                        continue
                    indices = tuple(sorted(indices, key=default_sort_key))
                    d[indices].append(scalar*remove_matelement(elem, *indices))
                    scalar = 1
            return [(MatrixElement(Add.fromiter(v), *k), k) for k, v in d.items()]
        elif isinstance(expr, KroneckerDelta):
            i1, i2 = expr.args
            if dimensions is not None:
                identity = Identity(dimensions[0])
            else:
                identity = S.One
            return [(MatrixElement(identity, i1, i2), (i1, i2))]
        elif isinstance(expr, MatrixElement):
            matrix_symbol, i1, i2 = expr.args
            if i1 in index_ranges:
                r1, r2 = index_ranges[i1]
                if r1 != 0 or matrix_symbol.shape[0] != r2+1:
                    raise ValueError("index range mismatch: {0} vs. (0, {1})".format(
                        (r1, r2), matrix_symbol.shape[0]))
            if i2 in index_ranges:
                r1, r2 = index_ranges[i2]
                if r1 != 0 or matrix_symbol.shape[1] != r2+1:
                    raise ValueError("index range mismatch: {0} vs. (0, {1})".format(
                        (r1, r2), matrix_symbol.shape[1]))
            if (i1 == i2) and (i1 in index_ranges):
                return [(trace(matrix_symbol), None)]
            return [(MatrixElement(matrix_symbol, i1, i2), (i1, i2))]
        elif isinstance(expr, Sum):
            return recurse_expr(
                expr.args[0],
                index_ranges={i[0]: i[1:] for i in expr.args[1:]}
            )
        else:
            return [(expr, None)]

    retvals = recurse_expr(expr)
    factors, indices = zip(*retvals)
    retexpr = Mul.fromiter(factors)
    if len(indices) == 0 or list(set(indices)) == [None]:
        return retexpr
    if first_index is None:
        for i in indices:
            if i is not None:
                ind0 = i
                break
        return remove_matelement(retexpr, *ind0)
    else:
        return remove_matelement(retexpr, first_index, last_index)

def _print_MatrixElement(self, expr):
    return self.parenthesize(expr.parent, PRECEDENCE["Atom"], strict=True) \
        + '_{%s, %s}' % (expr.i, expr.j)

def _deal_with_super_sub(self, string):
    if '{' in string:
        return string

    name, supers, subs = split_super_sub(string)

    name = translate(name)
    supers = [translate(sup) for sup in supers]
    subs = [translate(sub) for sub in subs]

    # glue all items together:
    if len(supers) > 0:
        name += "^{%s}" % " ".join(supers)
    if len(subs) > 0:
        name += "_{%s}" % " ".join(subs)

    return name

def _print_Symbol(self, expr):
    if expr in self._settings['symbol_names']:
        return self._settings['symbol_names'][expr]

    return self._deal_with_super_sub(expr.name) if \
        '\\' not in expr.name else expr.name

def routine(self, name, expr, argument_sequence=None, global_vars=None):
    """Creates an Routine object that is appropriate for this language.

    This implementation is appropriate for at least C/Fortran.  Subclasses
    can override this if necessary.

    Here, we assume at most one return value (the l-value) which must be
    scalar.  Additional outputs are OutputArguments (e.g., pointers on
    right-hand-side or pass-by-reference).  Matrices are always returned
    via OutputArguments.  If ``argument_sequence`` is None, arguments will
    be ordered alphabetically, but with all InputArguments first, and then
    OutputArgument and InOutArguments.

    """

    if self.cse:
        from sympy.simplify.cse_main import cse

        if is_sequence(expr) and not isinstance(expr, (MatrixBase, MatrixExpr)):
            if not expr:
                raise ValueError("No expression given")
            for e in expr:
                if not e.is_Equality:
                    raise CodeGenError("Lists of expressions must all be Equalities. {} is not.".format(e))

            # create a list of right hand sides and simplify them
            rhs = [e.rhs for e in expr]
            common, simplified = cse(rhs)

            # pack the simplified expressions back up with their left hand sides
            expr = [Equality(e.lhs, rhs) for e, rhs in zip(expr, simplified)]
        else:
            rhs = [expr]

            if isinstance(expr, Equality):
                common, simplified = cse(expr.rhs) #, ignore=in_out_args)
                expr = Equality(expr.lhs, simplified[0])
            else:
                common, simplified = cse(expr)
                expr = simplified

        local_vars = [Result(b,a) for a,b in common]
        local_symbols = set([a for a,_ in common])
        local_expressions = Tuple(*[b for _,b in common])
    else:
        local_expressions = Tuple()

    if is_sequence(expr) and not isinstance(expr, (MatrixBase, MatrixExpr)):
        if not expr:
            raise ValueError("No expression given")
        expressions = Tuple(*expr)
    else:
        expressions = Tuple(expr)

    if self.cse:
        if {i.label for i in expressions.atoms(Idx)} != set():
            raise CodeGenError("CSE and Indexed expressions do not play well together yet")
    else:
        # local variables for indexed expressions
        local_vars = {i.label for i in expressions.atoms(Idx)}
        local_symbols = local_vars

    # global variables
    global_vars = set() if global_vars is None else set(global_vars)

    # symbols that should be arguments
    symbols = (expressions.free_symbols | local_expressions.free_symbols) - local_symbols - global_vars
    new_symbols = set([])
    new_symbols.update(symbols)

    for symbol in symbols:
        if isinstance(symbol, Idx):
            new_symbols.remove(symbol)
            new_symbols.update(symbol.args[1].free_symbols)
        if isinstance(symbol, Indexed):
            new_symbols.remove(symbol)
    symbols = new_symbols

    # Decide whether to use output argument or return value
    return_val = []
    output_args = []
    for expr in expressions:
        if isinstance(expr, Equality):
            out_arg = expr.lhs
            expr = expr.rhs
            if isinstance(out_arg, Indexed):
                dims = tuple([ (S.Zero, dim - 1) for dim in out_arg.shape])
                symbol = out_arg.base.label
            elif isinstance(out_arg, Symbol):
                dims = []
                symbol = out_arg
            elif isinstance(out_arg, MatrixSymbol):
                dims = tuple([ (S.Zero, dim - 1) for dim in out_arg.shape])
                symbol = out_arg
            else:
                raise CodeGenError("Only Indexed, Symbol, or MatrixSymbol "
                                   "can define output arguments.")

            if expr.has(symbol):
                output_args.append(
                    InOutArgument(symbol, out_arg, expr, dimensions=dims))
            else:
                output_args.append(
                    OutputArgument(symbol, out_arg, expr, dimensions=dims))

            # remove duplicate arguments when they are not local variables
            if symbol not in local_vars:
                # avoid duplicate arguments
                symbols.remove(symbol)
        elif isinstance(expr, (ImmutableMatrix, MatrixSlice)):
            # Create a "dummy" MatrixSymbol to use as the Output arg
            out_arg = MatrixSymbol('out_%s' % abs(hash(expr)), *expr.shape)
            dims = tuple([(S.Zero, dim - 1) for dim in out_arg.shape])
            output_args.append(
                OutputArgument(out_arg, out_arg, expr, dimensions=dims))
        else:
            return_val.append(Result(expr))

    arg_list = []

    # setup input argument list
    array_symbols = {}
    for array in expressions.atoms(Indexed) | local_expressions.atoms(Indexed):
        array_symbols[array.base.label] = array
    for array in expressions.atoms(MatrixSymbol) | local_expressions.atoms(MatrixSymbol):
        array_symbols[array] = array

    for symbol in sorted(symbols, key=str):
        if symbol in array_symbols:
            dims = []
            array = array_symbols[symbol]
            for dim in array.shape:
                dims.append((S.Zero, dim - 1))
            metadata = {'dimensions': dims}
        else:
            metadata = {}

        arg_list.append(InputArgument(symbol, **metadata))

    output_args.sort(key=lambda x: str(x.name))
    arg_list.extend(output_args)

    if argument_sequence is not None:
        # if the user has supplied IndexedBase instances, we'll accept that
        new_sequence = []
        for arg in argument_sequence:
            if isinstance(arg, IndexedBase):
                new_sequence.append(arg.label)
            else:
                new_sequence.append(arg)
        argument_sequence = new_sequence

        missing = [x for x in arg_list if x.name not in argument_sequence]
        if missing:
            msg = "Argument list didn't specify: {0} "
            msg = msg.format(", ".join([str(m.name) for m in missing]))
            raise CodeGenArgumentListError(msg, missing)

        # create redundant arguments to produce the requested sequence
        name_arg_dict = {x.name: x for x in arg_list}
        new_args = []
        for symbol in argument_sequence:
            try:
                new_args.append(name_arg_dict[symbol])
            except KeyError:
                new_args.append(InputArgument(symbol))
        arg_list = new_args

    return Routine(name, arg_list, return_val, local_vars, global_vars)

def _prototype_arg(self, arg):
    mat_dec = "np.ndarray[{mtype}, ndim={ndim}] {name}"
    np_types = {'double': 'np.double_t',
                'int': 'np.int_t'}
    t = arg.get_datatype('c')
    if arg.dimensions:
        self._need_numpy = True
        ndim = len(arg.dimensions)
        mtype = np_types[t]
        return mat_dec.format(mtype=mtype, ndim=ndim, name=self._string_var(arg.name))
    else:
        return "%s %s" % (t, self._string_var(arg.name))

def __new__(cls, *args, **kwargs):
    evaluate = kwargs.get('evaluate', global_parameters.evaluate)
    on_morph = kwargs.get('on_morph', 'ignore')

    # unpack into coords
    coords = args[0] if len(args) == 1 else args

    # check args and handle quickly handle Point instances
    if isinstance(coords, Point):
        # even if we're mutating the dimension of a point, we
        # don't reevaluate its coordinates
        evaluate = False
        if len(coords) == kwargs.get('dim', len(coords)):
            return coords

    if not is_sequence(coords):
        raise TypeError(filldedent('''
            Expecting sequence of coordinates, not `{}`'''
                                   .format(func_name(coords))))
    # A point where only `dim` is specified is initialized
    # to zeros.
    if len(coords) == 0 and kwargs.get('dim', None):
        coords = (S.Zero,)*kwargs.get('dim')

    coords = Tuple(*coords)
    dim = kwargs.get('dim', len(coords))

    if len(coords) < 2:
        raise ValueError(filldedent('''
            Point requires 2 or more coordinates or
            keyword `dim` > 1.'''))
    if len(coords) != dim:
        message = ("Dimension of {} needs to be changed "
                   "from {} to {}.").format(coords, len(coords), dim)
        if on_morph == 'ignore':
            pass
        elif on_morph == "error":
            raise ValueError(message)
        elif on_morph == 'warn':
            warnings.warn(message)
        else:
            raise ValueError(filldedent('''
                    on_morph value should be 'error',
                    'warn' or 'ignore'.'''))
    if any(coords[dim:]):
        raise ValueError('Nonzero coordinates cannot be removed.')
    if any(a.is_number and im(a) for a in coords):
        raise ValueError('Imaginary coordinates are not permitted.')
    if not all(isinstance(a, Expr) for a in coords):
        raise TypeError('Coordinates must be valid SymPy expressions.')

    # pad with zeros appropriately
    coords = coords[:dim] + (S.Zero,)*(dim - len(coords))

    # Turn any Floats into rationals and simplify
    # any expressions before we instantiate
    if evaluate:
        coords = coords.xreplace({
            f: simplify(nsimplify(f, rational=True))
             for f in coords.atoms(Float)})

    # return 2D or 3D instances
    if len(coords) == 2:
        kwargs['_nocheck'] = True
        return Point2D(*coords, **kwargs)
    elif len(coords) == 3:
        kwargs['_nocheck'] = True
        return Point3D(*coords, **kwargs)

    # the general Point
    return GeometryEntity.__new__(cls, *coords)

def visit_Call(self, node):
    new_node = self.generic_visit(node)
    if isinstance(node.func, ast.Name) and node.func.id in self.functions:
        new_node.keywords.append(ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load())))
    return new_node

class EvaluateFalseTransformer(ast.NodeTransformer):
    operators = {
        ast.Add: 'Add',
        ast.Mult: 'Mul',
        ast.Pow: 'Pow',
        ast.Sub: 'Add',
        ast.Div: 'Mul',
        ast.BitOr: 'Or',
        ast.BitAnd: 'And',
        ast.BitXor: 'Not',
    }
    functions = (
        'Abs', 'im', 're', 'sign', 'arg', 'conjugate',
        'acos', 'acot', 'acsc', 'asec', 'asin', 'atan',
        'acosh', 'acoth', 'acsch', 'asech', 'asinh', 'atanh',
        'cos', 'cot', 'csc', 'sec', 'sin', 'tan',
        'cosh', 'coth', 'csch', 'sech', 'sinh', 'tanh',
        'exp', 'ln', 'log', 'sqrt', 'cbrt',
    )

    def flatten(self, args, func):
        result = []
        for arg in args:
            if isinstance(arg, ast.Call):
                arg_func = arg.func
                if isinstance(arg_func, ast.Call):
                    arg_func = arg_func.func
                if arg_func.id == func:
                    result.extend(self.flatten(arg.args, func))
                else:
                    result.append(arg)
            else:
                result.append(arg)
        return result

    def visit_BinOp(self, node):
        if node.op.__class__ in self.operators:
            sympy_class = self.operators[node.op.__class__]
            right = self.visit(node.right)
            left = self.visit(node.left)

            rev = False
            if isinstance(node.op, ast.Sub):
                right = ast.Call(
                    func=ast.Name(id='Mul', ctx=ast.Load()),
                    args=[ast.UnaryOp(op=ast.USub(), operand=ast.Num(1)), right],
                    keywords=[ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load()))],
                    starargs=None,
                    kwargs=None
                )
            elif isinstance(node.op, ast.Div):
                if isinstance(node.left, ast.UnaryOp):
                    left, right = right, left
                    rev = True
                    left = ast.Call(
                    func=ast.Name(id='Pow', ctx=ast.Load()),
                    args=[left, ast.UnaryOp(op=ast.USub(), operand=ast.Num(1))],
                    keywords=[ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load()))],
                    starargs=None,
                    kwargs=None
                )
                else:
                    right = ast.Call(
                    func=ast.Name(id='Pow', ctx=ast.Load()),
                    args=[right, ast.UnaryOp(op=ast.USub(), operand=ast.Num(1))],
                    keywords=[ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load()))],
                    starargs=None,
                    kwargs=None
                )

            if rev:  # undo reversal
                left, right = right, left
            new_node = ast.Call(
                func=ast.Name(id=sympy_class, ctx=ast.Load()),
                args=[left, right],
                keywords=[ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load()))],
                starargs=None,
                kwargs=None
            )

            if sympy_class in ('Add', 'Mul'):
                # Denest Add or Mul as appropriate
                new_node.args = self.flatten(new_node.args, sympy_class)

            return new_node
        return node

    def visit_Call(self, node):
        new_node = self.generic_visit(node)
        if isinstance(node.func, ast.Name) and node.func.id in self.functions:
            new_node.keywords.append(ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load())))
        return new_node

def __new__(cls, *args, _nocheck=False, **kwargs):
    if not _nocheck:
        kwargs['dim'] = 2
        args = Point(*args, **kwargs)
    return GeometryEntity.__new__(cls, *args)

def _collect_factor_and_dimension(self, expr):
    """
    Return tuple with scale factor expression and dimension expression.
    """
    from sympy.physics.units import Quantity
    if isinstance(expr, Quantity):
        return expr.scale_factor, expr.dimension
    elif isinstance(expr, Mul):
        factor = 1
        dimension = Dimension(1)
        for arg in expr.args:
            arg_factor, arg_dim = self._collect_factor_and_dimension(arg)
            factor *= arg_factor
            dimension *= arg_dim
        return factor, dimension
    elif isinstance(expr, Pow):
        factor, dim = self._collect_factor_and_dimension(expr.base)
        exp_factor, exp_dim = self._collect_factor_and_dimension(expr.exp)
        if self.get_dimension_system().is_dimensionless(exp_dim):
            exp_dim = 1
        return factor ** exp_factor, dim ** (exp_factor * exp_dim)
    elif isinstance(expr, Add):
        factor, dim = self._collect_factor_and_dimension(expr.args[0])
        for addend in expr.args[1:]:
            addend_factor, addend_dim = \
                self._collect_factor_and_dimension(addend)
            if dim != addend_dim:
                raise ValueError(
                    'Dimension of "{}" is {}, '
                    'but it should be {}'.format(
                        addend, addend_dim, dim))
            factor += addend_factor
        return factor, dim
    elif isinstance(expr, Derivative):
        factor, dim = self._collect_factor_and_dimension(expr.args[0])
        for independent, count in expr.variable_count:
            ifactor, idim = self._collect_factor_and_dimension(independent)
            factor /= ifactor**count
            dim /= idim**count
        return factor, dim
    elif isinstance(expr, Function):
        fds = [self._collect_factor_and_dimension(
            arg) for arg in expr.args]
        return (expr.func(*(f[0] for f in fds)),
                *(d[1] for d in fds))
    elif isinstance(expr, Dimension):
        return S.One, expr
    else:
        return expr, Dimension(1)

def __rmul__(self, a):
    """Implementation of reverse multiplication method."""
    return a.__mul__(self)

def _trigsimp(expr, deep=False):
    # protect the cache from non-trig patterns; we only allow
    # trig patterns to enter the cache
    if expr.has(*_trigs):
        return __trigsimp(expr, deep)
    return expr

def __trigsimp(expr, deep=False):
    """recursive helper for trigsimp"""
    from sympy.simplify.fu import TR10i

    if _trigpat is None:
        _trigpats()
    a, b, c, d, matchers_division, matchers_add, \
    matchers_identity, artifacts = _trigpat

    if expr.is_Mul:
        # do some simplifications like sin/cos -> tan:
        if not expr.is_commutative:
            com, nc = expr.args_cnc()
            expr = _trigsimp(Mul._from_args(com), deep)*Mul._from_args(nc)
        else:
            for i, (pattern, simp, ok1, ok2) in enumerate(matchers_division):
                if not _dotrig(expr, pattern):
                    continue

                newexpr = _match_div_rewrite(expr, i)
                if newexpr is not None:
                    if newexpr != expr:
                        expr = newexpr
                        break
                    else:
                        continue

                # use SymPy matching instead
                res = expr.match(pattern)
                if res and res.get(c, 0):
                    if not res[c].is_integer:
                        ok = ok1.subs(res)
                        if not ok.is_positive:
                            continue
                        ok = ok2.subs(res)
                        if not ok.is_positive:
                            continue
                    # if "a" contains any of trig or hyperbolic funcs with
                    # argument "b" then skip the simplification
                    if any(w.args[0] == res[b] for w in res[a].atoms(
                            TrigonometricFunction, HyperbolicFunction)):
                        continue
                    # simplify and finish:
                    expr = simp.subs(res)
                    break  # process below

    if expr.is_Add:
        args = []
        for term in expr.args:
            if not term.is_commutative:
                com, nc = term.args_cnc()
                nc = Mul._from_args(nc)
                term = Mul._from_args(com)
            else:
                nc = S.One
            term = _trigsimp(term, deep)
            for pattern, result in matchers_identity:
                res = term.match(pattern)
                if res is not None:
                    term = result.subs(res)
                    break
            args.append(term*nc)
        if args != expr.args:
            expr = Add(*args)
            expr = min(expr, expand(expr), key=count_ops)
        if expr.is_Add:
            for pattern, result in matchers_add:
                if not _dotrig(expr, pattern):
                    continue
                expr = TR10i(expr)
                if expr.has(HyperbolicFunction):
                    res = expr.match(pattern)
                    # if "d" contains any trig or hyperbolic funcs with
                    # argument "a" or "b" then skip the simplification;
                    # this isn't perfect -- see tests
                    if res is None or not (a in res and b in res) or any(
                        w.args[0] in (res[a], res[b]) for w in res[d].atoms(
                            TrigonometricFunction, HyperbolicFunction)):
                        continue
                    expr = result.subs(res)
                    break

        # Reduce any lingering artifacts, such as sin(x)**2 changing
        # to 1 - cos(x)**2 when sin(x)**2 was "simpler"
        for pattern, result, ex in artifacts:
            if not _dotrig(expr, pattern):
                continue
            # Substitute a new wild that excludes some function(s)
            # to help influence a better match. This is because
            # sometimes, for example, 'a' would match sec(x)**2
            a_t = Wild('a', exclude=[ex])
            pattern = pattern.subs(a, a_t)
            result = result.subs(a, a_t)

            m = expr.match(pattern)
            was = None
            while m and was != expr:
                was = expr
                if m[a_t] == 0 or \
                        -m[a_t] in m[c].args or m[a_t] + m[c] == 0:
                    break
                if d in m and m[a_t]*m[d] + m[c] == 0:
                    break
                expr = result.subs(m)
                m = expr.match(pattern)
                m.setdefault(c, S.Zero)

    elif expr.is_Mul or expr.is_Pow or deep and expr.args:
        expr = expr.func(*[_trigsimp(a, deep) for a in expr.args])

    try:
        if not expr.has(*_trigs):
            raise TypeError
        e = expr.atoms(exp)
        new = expr.rewrite(exp, deep=deep)
        if new == e:
            raise TypeError
        fnew = factor(new)
        if fnew != new:
            new = sorted([new, factor(new)], key=count_ops)[0]
        # if all exp that were introduced disappeared then accept it
        if not (new.atoms(exp) - e):
            expr = new
    except TypeError:
        pass

    return expr

def _blockmul(self, other):
    if (isinstance(other, BlockMatrix) and
            self.colblocksizes == other.rowblocksizes):
        return BlockMatrix(self.blocks*other.blocks)

    return self * other

def bc_matmul(expr):
    if isinstance(expr, MatPow):
        if expr.args[1].is_Integer:
            factor, matrices = (1, [expr.args[0]]*expr.args[1])
        else:
            return expr
    else:
        factor, matrices = expr.as_coeff_matrices()

    i = 0
    while (i+1 < len(matrices)):
        A, B = matrices[i:i+2]
        if isinstance(A, BlockMatrix) and isinstance(B, BlockMatrix):
            matrices[i] = A._blockmul(B)
            matrices.pop(i+1)
        elif isinstance(A, BlockMatrix):
            matrices[i] = A._blockmul(BlockMatrix([[B]]))
            matrices.pop(i+1)
        elif isinstance(B, BlockMatrix):
            matrices[i] = BlockMatrix([[A]])._blockmul(B)
            matrices.pop(i+1)
        else:
            i+=1
    return MatMul(factor, *matrices).doit()

def __new__(cls, m, n):
    m, n = _sympify(m), _sympify(n)
    cls._check_dim(m)
    cls._check_dim(n)

    return super(ZeroMatrix, cls).__new__(cls, m, n)

def eval(cls, arg):
    from sympy import im
    v = cls._eval_number(arg)
    if v is not None:
        return v

    if arg.is_integer or arg.is_finite is False:
        return arg
    if arg.is_imaginary or (S.ImaginaryUnit*arg).is_real:
        i = im(arg)
        if not i.has(S.ImaginaryUnit):
            return cls(i)*S.ImaginaryUnit
        return cls(arg, evaluate=False)

    # Integral, numerical, symbolic part
    ipart = npart = spart = S.Zero

    # Extract integral (or complex integral) terms
    terms = Add.make_args(arg)

    for t in terms:
        if t.is_integer or (t.is_imaginary and im(t).is_integer):
            ipart += t
        elif t.has(Symbol):
            spart += t
        else:
            npart += t

    if not (npart or spart):
        return ipart

    # Evaluate npart numerically if independent of spart
    if npart and (
        not spart or
        npart.is_real and (spart.is_imaginary or (S.ImaginaryUnit*spart).is_real) or
            npart.is_imaginary and spart.is_real):
        try:
            r, i = get_integer_part(
                npart, cls._dir, {}, return_ints=True)
            ipart += Integer(r) + Integer(i)*S.ImaginaryUnit
            npart = S.Zero
        except (PrecisionExhausted, NotImplementedError):
            pass

    spart += npart
    if not spart:
        return ipart
    elif spart.is_imaginary or (S.ImaginaryUnit*spart).is_real:
        return ipart + cls(im(spart), evaluate=False)*S.ImaginaryUnit
    elif isinstance(spart, (floor, ceiling)):
        return ipart + spart
    else:
        return ipart + cls(spart, evaluate=False)

def _eval_power(self, expt):
    if expt.is_positive:
        return self
    if expt.is_negative:
        return S.ComplexInfinity
    if expt.is_extended_real is False:
        return S.NaN
    # infinities are already handled with pos and neg
    # tests above; now throw away leading numbers on Mul
    # exponent
    coeff, terms = expt.as_coeff_Mul()
    if coeff.is_negative:
        return S.ComplexInfinity**terms
    if coeff is not S.One:  # there is a Number to discard
        return self**terms

class NegativeInfinity(Number, metaclass=Singleton):
    """Negative infinite quantity.

    NegativeInfinity is a singleton, and can be accessed
    by ``S.NegativeInfinity``.

    See Also
    ========

    Infinity
    """

    is_extended_real = True
    is_complex = False
    is_commutative = True
    is_infinite = True
    is_comparable = True
    is_extended_negative = True
    is_number = True
    is_prime = False

    __slots__ = ()

    def __new__(cls):
        return AtomicExpr.__new__(cls)

    def _latex(self, printer):
        return r"-\infty"

    def _eval_subs(self, old, new):
        if self == old:
            return new

    def _eval_evalf(self, prec=None):
        return Float('-inf')

    def evalf(self, prec=None, **options):
        return self._eval_evalf(prec)

    @_sympifyit('other', NotImplemented)
    def __add__(self, other):
        if isinstance(other, Number) and global_parameters.evaluate:
            if other is S.Infinity or other is S.NaN:
                return S.NaN
            return self
        return Number.__add__(self, other)
    __radd__ = __add__

    @_sympifyit('other', NotImplemented)
    def __sub__(self, other):
        if isinstance(other, Number) and global_parameters.evaluate:
            if other is S.NegativeInfinity or other is S.NaN:
                return S.NaN
            return self
        return Number.__sub__(self, other)

    @_sympifyit('other', NotImplemented)
    def __rsub__(self, other):
        return (-self).__add__(other)

    @_sympifyit('other', NotImplemented)
    def __mul__(self, other):
        if isinstance(other, Number) and global_parameters.evaluate:
            if other.is_zero or other is S.NaN:
                return S.NaN
            if other.is_extended_positive:
                return self
            return S.Infinity
        return Number.__mul__(self, other)
    __rmul__ = __mul__

    @_sympifyit('other', NotImplemented)
    def __truediv__(self, other):
        if isinstance(other, Number) and global_parameters.evaluate:
            if other is S.Infinity or \
                other is S.NegativeInfinity or \
                    other is S.NaN:
                return S.NaN
            if other.is_extended_nonnegative:
                return self
            return S.Infinity
        return Number.__truediv__(self, other)

    def __abs__(self):
        return S.Infinity

    def __neg__(self):
        return S.Infinity

    def _eval_power(self, expt):
        """
        ``expt`` is symbolic object but not equal to 0 or 1.

        ================ ======= ==============================
        Expression       Result  Notes
        ================ ======= ==============================
        ``(-oo) ** nan`` ``nan``
        ``(-oo) ** oo``  ``nan``
        ``(-oo) ** -oo`` ``nan``
        ``(-oo) ** e``   ``oo``  ``e`` is positive even integer
        ``(-oo) ** o``   ``-oo`` ``o`` is positive odd integer
        ================ ======= ==============================

        See Also
        ========

        Infinity
        Pow
        NaN

        """
        if expt.is_number:
            if expt is S.NaN or \
                expt is S.Infinity or \
                    expt is S.NegativeInfinity:
                return S.NaN

            if isinstance(expt, Integer) and expt.is_extended_positive:
                if expt.is_odd:
                    return S.NegativeInfinity
                else:
                    return S.Infinity

            return S.NegativeOne**expt*S.Infinity**expt

    def _as_mpf_val(self, prec):
        return mlib.fninf

    def _sage_(self):
        import sage.all as sage
        return -(sage.oo)

    def __hash__(self):
        return super().__hash__()

    def __eq__(self, other):
        return other is S.NegativeInfinity or other == float('-inf')

    def __ne__(self, other):
        return other is not S.NegativeInfinity and other != float('-inf')

    __gt__ = Expr.__gt__
    __ge__ = Expr.__ge__
    __lt__ = Expr.__lt__
    __le__ = Expr.__le__

    @_sympifyit('other', NotImplemented)
    def __mod__(self, other):
        if not isinstance(other, Expr):
            return NotImplemented
        return S.NaN

    __rmod__ = __mod__

    def floor(self):
        return self

    def ceiling(self):
        return self

    def as_powers_dict(self):
        return {S.NegativeOne: 1, S.Infinity: 1}

def _eval_power(self, expt):
    """
    ``expt`` is symbolic object but not equal to 0 or 1.

    ================ ======= ==============================
    Expression       Result  Notes
    ================ ======= ==============================
    ``oo ** nan``    ``nan``
    ``oo ** -p``     ``0``   ``p`` is number, ``oo``
    ================ ======= ==============================

    See Also
    ========
    Pow
    NaN
    NegativeInfinity

    """
    from sympy.functions import re

    if expt.is_extended_positive:
        return S.Infinity
    if expt.is_extended_negative:
        return S.Zero
    if expt is S.NaN:
        return S.NaN
    if expt is S.ComplexInfinity:
        return S.NaN
    if expt.is_extended_real is False and expt.is_number:
        expt_real = re(expt)
        if expt_real.is_positive:
            return S.ComplexInfinity
        if expt_real.is_negative:
            return S.Zero
        if expt_real.is_zero:
            return S.NaN

        return self**expt.evalf()

class AtomicExpr(Atom, Expr):
    """
    A parent class for object which are both atoms and Exprs.

    For example: Symbol, Number, Rational, Integer, ...
    But not: Add, Mul, Pow, ...
    """
    is_number = False
    is_Atom = True

    __slots__ = ()

    def _eval_derivative(self, s):
        if self == s:
            return S.One
        return S.Zero

    def _eval_derivative_n_times(self, s, n):
        from sympy import Piecewise, Eq
        from sympy import Tuple, MatrixExpr
        from sympy.matrices.common import MatrixCommon
        if isinstance(s, (MatrixCommon, Tuple, Iterable, MatrixExpr)):
            return super()._eval_derivative_n_times(s, n)
        if self == s:
            return Piecewise((self, Eq(n, 0)), (1, Eq(n, 1)), (0, True))
        else:
            return Piecewise((self, Eq(n, 0)), (0, True))

    def _eval_is_polynomial(self, syms):
        return True

    def _eval_is_rational_function(self, syms):
        return True

    def _eval_is_meromorphic(self, x, a):
        from sympy.calculus.util import AccumBounds
        return (not self.is_Number or self.is_finite) and not isinstance(self, AccumBounds)

    def _eval_is_algebraic_expr(self, syms):
        return True

    def _eval_nseries(self, x, n, logx, cdir=0):
        return self

    @property
    def expr_free_symbols(self):
        return {self}

class Symbol(AtomicExpr, Boolean):
    """
    Assumptions:
       commutative = True

    You can override the default assumptions in the constructor.

    Examples
    ========

    >>> from sympy import symbols
    >>> A,B = symbols('A,B', commutative = False)
    >>> bool(A*B != B*A)
    True
    >>> bool(A*B*2 == 2*A*B) == True # multiplication by scalars is commutative
    True

    """

    is_comparable = False

    __slots__ = ('name',)

    is_Symbol = True
    is_symbol = True

    @property
    def _diff_wrt(self):
        """Allow derivatives wrt Symbols.

        Examples
        ========

            >>> from sympy import Symbol
            >>> x = Symbol('x')
            >>> x._diff_wrt
            True
        """
        return True

    @staticmethod
    def _sanitize(assumptions, obj=None):
        """Remove None, covert values to bool, check commutativity *in place*.
        """

        # be strict about commutativity: cannot be None
        is_commutative = fuzzy_bool(assumptions.get('commutative', True))
        if is_commutative is None:
            whose = '%s ' % obj.__name__ if obj else ''
            raise ValueError(
                '%scommutativity must be True or False.' % whose)

        # sanitize other assumptions so 1 -> True and 0 -> False
        for key in list(assumptions.keys()):
            v = assumptions[key]
            if v is None:
                assumptions.pop(key)
                continue
            assumptions[key] = bool(v)

    def _merge(self, assumptions):
        base = self.assumptions0
        for k in set(assumptions) & set(base):
            if assumptions[k] != base[k]:
                from sympy.utilities.misc import filldedent
                raise ValueError(filldedent('''
                    non-matching assumptions for %s: existing value
                    is %s and new value is %s''' % (
                    k, base[k], assumptions[k])))
        base.update(assumptions)
        return base

    def __new__(cls, name, **assumptions):
        """Symbols are identified by name and assumptions::

        >>> from sympy import Symbol
        >>> Symbol("x") == Symbol("x")
        True
        >>> Symbol("x", real=True) == Symbol("x", real=False)
        False

        """
        cls._sanitize(assumptions, cls)
        return Symbol.__xnew_cached_(cls, name, **assumptions)

    def __new_stage2__(cls, name, **assumptions):
        if not isinstance(name, str):
            raise TypeError("name should be a string, not %s" % repr(type(name)))

        obj = Expr.__new__(cls)
        obj.name = name

        # TODO: Issue #8873: Forcing the commutative assumption here means
        # later code such as ``srepr()`` cannot tell whether the user
        # specified ``commutative=True`` or omitted it.  To workaround this,
        # we keep a copy of the assumptions dict, then create the StdFactKB,
        # and finally overwrite its ``._generator`` with the dict copy.  This
        # is a bit of a hack because we assume StdFactKB merely copies the
        # given dict as ``._generator``, but future modification might, e.g.,
        # compute a minimal equivalent assumption set.
        tmp_asm_copy = assumptions.copy()

        # be strict about commutativity
        is_commutative = fuzzy_bool(assumptions.get('commutative', True))
        assumptions['commutative'] = is_commutative
        obj._assumptions = StdFactKB(assumptions)
        obj._assumptions._generator = tmp_asm_copy  # Issue #8873
        return obj

    __xnew__ = staticmethod(
        __new_stage2__)            # never cached (e.g. dummy)
    __xnew_cached_ = staticmethod(
        cacheit(__new_stage2__))   # symbols are always cached

    def __getnewargs__(self):
        return (self.name,)

    def __getstate__(self):
        return {'_assumptions': self._assumptions}

    def _hashable_content(self):
        # Note: user-specified assumptions not hashed, just derived ones
        return (self.name,) + tuple(sorted(self.assumptions0.items()))

    def _eval_subs(self, old, new):
        from sympy.core.power import Pow
        if old.is_Pow:
            return Pow(self, S.One, evaluate=False)._eval_subs(old, new)

    @property
    def assumptions0(self):
        return {key: value for key, value
                in self._assumptions.items() if value is not None}

    @cacheit
    def sort_key(self, order=None):
        return self.class_key(), (1, (self.name,)), S.One.sort_key(), S.One

    def as_dummy(self):
        # only put commutativity in explicitly if it is False
        return Dummy(self.name) if self.is_commutative is not False \
            else Dummy(self.name, commutative=self.is_commutative)

    def as_real_imag(self, deep=True, **hints):
        from sympy import im, re
        if hints.get('ignore') == self:
            return None
        else:
            return (re(self), im(self))

    def _sage_(self):
        import sage.all as sage
        return sage.var(self.name)

    def is_constant(self, *wrt, **flags):
        if not wrt:
            return False
        return not self in wrt

    @property
    def free_symbols(self):
        return {self}

    binary_symbols = free_symbols  # in this case, not always

    def as_set(self):
        return S.UniversalSet

class Expr(Basic, EvalfMixin):
    """
    Base class for algebraic expressions.

    Explanation
    ===========

    Everything that requires arithmetic operations to be defined
    should subclass this class, instead of Basic (which should be
    used only for argument storage and expression manipulation, i.e.
    pattern matching, substitutions, etc).

    If you want to override the comparisons of expressions:
    Should use _eval_is_ge for inequality, or _eval_is_eq, with multiple dispatch.
    _eval_is_ge return true if x >= y, false if x < y, and None if the two types
    are not comparable or the comparison is indeterminate

    See Also
    ========

    sympy.core.basic.Basic
    """

    __slots__ = ()  # type: tTuple[str, ...]

    is_scalar = True  # self derivative is 1

    @property
    def _diff_wrt(self):
        """Return True if one can differentiate with respect to this
        object, else False.

        Explanation
        ===========

        Subclasses such as Symbol, Function and Derivative return True
        to enable derivatives wrt them. The implementation in Derivative
        separates the Symbol and non-Symbol (_diff_wrt=True) variables and
        temporarily converts the non-Symbols into Symbols when performing
        the differentiation. By default, any object deriving from Expr
        will behave like a scalar with self.diff(self) == 1. If this is
        not desired then the object must also set `is_scalar = False` or
        else define an _eval_derivative routine.

        Note, see the docstring of Derivative for how this should work
        mathematically. In particular, note that expr.subs(yourclass, Symbol)
        should be well-defined on a structural level, or this will lead to
        inconsistent results.

        Examples
        ========

        >>> from sympy import Expr
        >>> e = Expr()
        >>> e._diff_wrt
        False
        >>> class MyScalar(Expr):
        ...     _diff_wrt = True
        ...
        >>> MyScalar().diff(MyScalar())
        1
        >>> class MySymbol(Expr):
        ...     _diff_wrt = True
        ...     is_scalar = False
        ...
        >>> MySymbol().diff(MySymbol())
        Derivative(MySymbol(), MySymbol())
        """
        return False

    @cacheit
    def sort_key(self, order=None):

        coeff, expr = self.as_coeff_Mul()

        if expr.is_Pow:
            expr, exp = expr.args
        else:
            expr, exp = expr, S.One

        if expr.is_Dummy:
            args = (expr.sort_key(),)
        elif expr.is_Atom:
            args = (str(expr),)
        else:
            if expr.is_Add:
                args = expr.as_ordered_terms(order=order)
            elif expr.is_Mul:
                args = expr.as_ordered_factors(order=order)
            else:
                args = expr.args

            args = tuple(
                [ default_sort_key(arg, order=order) for arg in args ])

        args = (len(args), tuple(args))
        exp = exp.sort_key(order=order)

        return expr.class_key(), args, exp, coeff

    def __hash__(self) -> int:
        # hash cannot be cached using cache_it because infinite recurrence
        # occurs as hash is needed for setting cache dictionary keys
        h = self._mhash
        if h is None:
            h = hash((type(self).__name__,) + self._hashable_content())
            self._mhash = h
        return h

    def _hashable_content(self):
        """Return a tuple of information about self that can be used to
        compute the hash. If a class defines additional attributes,
        like ``name`` in Symbol, then this method should be updated
        accordingly to return such relevant attributes.
        Defining more than _hashable_content is necessary if __eq__ has
        been defined by a class. See note about this in Basic.__eq__."""
        return self._args

    def __eq__(self, other):
        try:
            other = _sympify(other)
            if not isinstance(other, Expr):
                return False
        except (SympifyError, SyntaxError):
            return False
        # check for pure number expr
        if  not (self.is_Number and other.is_Number) and (
                type(self) != type(other)):
            return False
        a, b = self._hashable_content(), other._hashable_content()
        if a != b:
            return False
        # check number *in* an expression
        for a, b in zip(a, b):
            if not isinstance(a, Expr):
                continue
            if a.is_Number and type(a) != type(b):
                return False
        return True

    # ***************
    # * Arithmetics *
    # ***************
    # Expr and its sublcasses use _op_priority to determine which object
    # passed to a binary special method (__mul__, etc.) will handle the
    # operation. In general, the 'call_highest_priority' decorator will choose
    # the object with the highest _op_priority to handle the call.
    # Custom subclasses that want to define their own binary special methods
    # should set an _op_priority value that is higher than the default.
    #
    # **NOTE**:
    # This is a temporary fix, and will eventually be replaced with
    # something better and more powerful.  See issue 5510.
    _op_priority = 10.0

    @property
    def _add_handler(self):
        return Add

    @property
    def _mul_handler(self):
        return Mul

    def __pos__(self):
        return self

    def __neg__(self):
